local config = {
  ui_story_5012_50120101_1_dialog_content = "Gaah!",
  ui_story_5012_50120101_2_dialog_content = "Kita hampir kehabisan waktu...",
  ui_story_5012_50120101_3_dialog_content = "Graaaaaagh!",
  ui_story_5012_50120101_4_dialog_content = "Demi... White Night...",
  ui_story_5012_50120101_5_dialog_content = "Grrr...",
  ui_story_5012_50120101_6_dialog_content = "Kita... Kita menang!",
  ui_story_5012_50120101_7_dialog_content = "Apa itu matahari?",
  ui_story_5012_50120101_8_dialog_content = "Tidak, selama ini kita...",
  ui_story_5012_50120101_9_dialog_content = "<size=45>Sudah kehilangan matahari...</size>",
  ui_story_5012_50120101_10_dialog_content = "...",
  ui_story_5012_50120101_11_dialog_content = "Lalu, ini...?",
  ui_story_5012_50120101_12_dialog_content = "Aku sudah membuatkan teh untuk Anda, Yang Mulia. Semoga Anda suka.",
  ui_story_5012_50120101_13_dialog_content = "... Yang Mulia, Anda berkeringat.",
  ui_story_5012_50120101_14_dialog_content = "Tadi aku <color=#FFB400>bermimpi</color>.",
  ui_story_5012_50120101_15_dialog_content = "Mimpi buruk?",
  ui_story_5012_50120101_16_dialog_content = "Tidak juga, tapi aku masih berusaha memahaminya.",
  ui_story_5012_50120101_17_dialog_content = "Begitukah? Itu jarang terjadi. Kalau tak keberatan, bersediakah Anda menceritakan mimpi itu?",
  ui_story_5012_50120101_18_dialog_content = "Dalam mimpiku, awalnya terdengar suara genta angin.",
  ui_story_5012_50120101_19_dialog_content = "Aku bermimpi aku terkurung dalam sangkar burung, dan pecahan kaca berserakan di mana-mana di atas tanah.",
  ui_story_5012_50120101_20_dialog_content = "Kulihat pecahan-pecahan itu lebih dekat, dan aku bisa melihat gambaran masa depan dalam setiap serpihannya.",
  ui_story_5012_50120101_21_dialog_content = "Aku melihat Eclipsite terakhir tumbang, panji-panji berkibaran di seluruh medan tempur, para Aurorian memberikan penghormatan untuk matahari.",
  ui_story_5012_50120101_22_dialog_content = "Tapi, aku juga melihat Lumopolis runtuh dari langit, Northland ditelan salju, Astra diselubungi malam tanpa akhir.",
  ui_story_5012_50120101_23_dialog_content = "Aku tak bisa berbuat apa pun, hanya bisa menyaksikan dunia ini hancur dan terlahir kembali, berulang kali.",
  ui_story_5012_50120101_24_dialog_content = "Mimpi-mimpi Anda selalu punya makna. Hamba rasa itu gambaran masa depan kita.",
  ui_story_5012_50120101_25_dialog_content = "Tapi, kali ini, mimpinya berbeda. Sama sekali tak seperti yang sudah-sudah.",
  ui_story_5012_50120101_26_dialog_content = "Seumpama masa depan adalah jendela, berarti hari ini masa depan itu telah dihancurkan oleh suatu kekuatan yang tak dikenal.",
  ui_story_5012_50120101_27_dialog_content = "Aku hanya bisa lihat sepotong-sepotong, bukan gambaran utuhnya.",
  ui_story_5012_50120101_28_dialog_content = "Yang Mulia, kalau Anda tak bisa melihatnya, berarti mungkin kaum Aurorian memang tidak ditakdirkan untuk mengetahui masa depan.",
  ui_story_5012_50120101_29_dialog_content = "Dan memang semestinya begitu.",
  ui_story_5012_50120101_30_dialog_content = "Kau benar...",
  ui_story_5012_50120101_31_dialog_content = "Tapi aku tak bisa mengabaikannya begitu saja.",
  ui_story_5012_50120101_32_dialog_content = "Anda terlalu keras kepada diri Anda sendiri, Yang Mulia.",
  ui_story_5012_50120101_33_dialog_content = "Tehnya bahkan belum Anda cicipi, lho.",
  ui_story_5012_50120101_34_dialog_content = "... Mmm, aku suka aromanya yang segar. Seingatku, aku belum pernah mencicipi teh seperti ini di Winter Palace.",
  ui_story_5012_50120101_35_dialog_content = "Ini ramuan istimewa teh bunga, khusus untuk <color=#FFB400>tahun baru</color>. Untunglah Anda menyukainya.",
  ui_story_5012_50120101_36_dialog_content = "Terima kasih, Pak.",
  ui_story_5012_50120101_37_dialog_content = "Kumohon, Yang Mulia, panggil hamba Novio. Begitu saja sudah cukup.",
  ui_story_5012_50120101_38_dialog_content = "Mendampingi Anda memang sudah jadi tugas hamba.",
  ui_story_5012_50120101_39_dialog_content = "Bagaimana persiapan tahun barunya?",
  ui_story_5012_50120101_40_dialog_content = "Lancar, sesuai harapan.",
  ui_story_5012_50120101_41_dialog_content = "Bagus. Nah, aku butuh bantuanmu untuk hal lain...",
  ui_story_5012_50120101_42_dialog_content = "Tolong kirimkan dua undangan dariku. Aku ingin mengundang beberapa <color=#FFB400>orang asing</color> untuk menghadiri perayaan tahun ini.",
  ui_story_5012_50120101_43_dialog_content = "Orang asing?",
  ui_story_5012_50120101_44_dialog_content = "Ya. Yang pertama adalah Carleen.",
  ui_story_5012_50120101_45_dialog_content = "Sudah bertahun-tahun dia tak berkunjung ke Northland. Semoga dia tak merasa asing dengan tempat ini.",
  ui_story_5012_50120101_46_dialog_content = "Yang kedua... untuk si Caelestite itu.",
  ui_story_5012_50120101_47_dialog_content = "Si Caelestite?",
  ui_story_5012_50120101_48_dialog_content = "Kau pasti tahu bahwa saat ini sebutan itu hanya mengarah pada satu orang saja, 'kan?",
  ui_story_5012_50120101_49_dialog_content = "Tentu saja, tapi kenapa dia harus diundang?",
  ui_story_5012_50120101_50_dialog_content = "Aku melihat si Caelestite itu dalam setiap kepingan gambaran masa depan.",
  ui_story_5012_50120101_51_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_5012_50120101_52_dialog_content = "Hawwo? Ada owang di wumah? Ayo, bangun!",
  ui_story_5012_50120101_53_dialog_content = "Ini aku, Tweety, dari Couwier Union!",
  ui_story_5012_50120101_54_dialog_content = "Navigatow! Ada suwat untukmu!",
  ui_story_5012_50120101_55_dialog_content = "Kau memang suka bekerja keras sejak dini, Tweety.",
  ui_story_5012_50120101_56_dialog_content = "Taruh saja suratnya di depan pintu.",
  ui_story_5012_50120101_57_dialog_content = "Tidak, tidak bisa! Suwat ini sangat spesial. Kau hawus membacanya sekawang!",
  ui_story_5012_50120101_58_dialog_content = "Dawi Winter Pawace, Northwand! Dan bertanda tangan Queen Bethwehem!",
  ui_story_5012_50120101_59_dialog_content = "Hah? Surat dari sang Ratu?",
  ui_story_5012_50120101_60_dialog_content = "Cepatt, jangan buang-buang waktu. Masih banyak suwat lain yang hawus kuantawkan!",
  ui_story_5012_50120101_61_dialog_content = "Baiklah, baiklah, aku ke sana.",
  ui_story_5012_50120101_62_dialog_content = "Coba kulihat... Undangan?",
  ui_story_5012_50120101_63_dialog_content = "\"Bethlehem, Ratu Northland, dengan ini mengundang Anda untuk menghadiri Perayaan Tahun Baru.\"",
  ui_story_5012_50120101_64_dialog_content = "Wow, Upacawa Tahun Bawu!",
  ui_story_5012_50120101_65_dialog_content = "Kalau sudah selesai mengantawkan suwat-suwat ini, aku juga mau ikut ke sana! Kita bisa mewayakannya bewsama!",
  ui_story_5012_50120101_66_dialog_content = "Pewayaan Tahun Bawu di Northwand selalu seru!",
  ui_story_5012_50120101_67_dialog_content = "Anu, kalau aku tak datang, apa boleh?",
  ui_story_5012_50120101_68_dialog_content = "Ah? Memangnya kenapa? Apa ada tempat yang lebih bagus yang ingin kaudatangi?",
  ui_story_5012_50120101_69_dialog_content = "Aku baru saja pulang dari perayaan di Lumopolis, dan sekarang masih ada Perayaan Tahun Baru di Northland...",
  ui_story_5012_50120101_70_dialog_content = "Kenapa sih aku harus menghadiri semua perayaan itu?",
  ui_story_5012_50120101_71_dialog_content = "Memangnya aku ini maskot universal?",
  ui_story_5012_50120101_72_dialog_content = "Lagi pula, sekarang kan musim dingin! Lebih baik aku tinggal di dalam Colossus saja daripada pergi ke tempat yang lebih dingin!",
  ui_story_5012_50120101_73_dialog_content = "Yang kaupegang itu apa?",
  ui_story_5012_50120101_74_dialog_content = "Hai, Carween! Ada suwat untukmu juga!",
  ui_story_5012_50120101_75_dialog_content = "Suwat dawi Queen Bethwehem, sama sepewti PlayerName.",
  ui_story_5012_50120101_76_dialog_content = "Apa suratmu juga berisi undangan ke Perayaan Tahun Baru?",
  ui_story_5012_50120101_77_dialog_content = "Iya.",
  ui_story_5012_50120101_78_dialog_content = "Aku tak menyangka, sang Ratu ternyata sangat ramah. Aku penasaran apa beliau juga mengirimkan undangan untuk semua orang...",
  ui_story_5012_50120101_79_dialog_content = "Undangan apa? Apa aku juga dapat?",
  ui_story_5012_50120101_80_dialog_content = "Anu, seingatku, tahun ini hanya ada dua undangan.",
  ui_story_5012_50120101_81_dialog_content = "...",
  ui_story_5012_50120101_82_dialog_content = "Yah, sebenarnya aku agak sibuk, jadi aku terpaksa menolaknya dengan sopan.",
  ui_story_5012_50120101_83_dialog_content = "Perayaan itu perlu dihadiri.",
  ui_story_5012_50120101_84_dialog_content = "Hah?",
  ui_story_5012_50120101_85_dialog_content = "Ini undangan dari sang Ratu. Aku harus menghadirinya.",
  ui_story_5012_50120101_86_dialog_content = "Oh... Baiklah, semoga perjalananmu aman...",
  ui_story_5012_50120101_87_dialog_content = "Kau juga harus menghadirinya.",
  ui_story_5012_50120101_88_dialog_content = "Kenapa?",
  ui_story_5012_50120101_89_dialog_content = "Karena sang Ratu mengundangmu.",
  ui_story_5012_50120101_90_dialog_content = "Tapi...",
  ui_story_5012_50120101_91_dialog_content = "Hei, undangan ini bilang kita boleh mengajak satu anggota keluarga kita...",
  ui_story_5012_50120101_92_dialog_content = "Anggota keluarga? Tapi, aku bahkan belum yakin mau menghadirnya atau tidak!",
  ui_story_5012_50120101_93_dialog_content = "Ehem. Memangnya siapa yang membicarakanmu, PlayerName?",
  ui_story_5012_50120101_94_dialog_content = "Kau tak keberatan, 'kan, mengajakku, teman sekelasmu ini, sebagai anggota keluargamu? Iya, 'kan, Carleen?",
  ui_story_5012_50120101_95_dialog_content = "Aku tak keberatan, tapi kau harus janji...",
  ui_story_5012_50120101_96_dialog_content = "Jangan khawatir, aku tak akan bertingkah memalukan!",
  ui_story_5012_50120101_97_dialog_content = "Lagi pula, apa kau lupa kalau aku baru saja bertemu Her Majesty Bethlehem di Lumopolis?",
  ui_story_5012_50120101_98_dialog_content = "Kalau begitu, kemasi barang-barangmu. Kau juga, PlayerName.",
  ui_story_5012_50120101_99_dialog_content = "Perjalanan ke Northland butuh waktu lama. Kita harus berangkat sesegera mungkin.",
  ui_story_5012_50120101_100_dialog_content = "Tunggu, memangnya aku tak berhak berpendapat? Ini kan undangan, bukan surat perintah!",
  ui_story_5012_50120101_101_dialog_content = "Terima kasih, Tweety. Silakan lanjutkan pekerjaanmu.",
  ui_story_5012_50120101_102_dialog_content = "Baiklah! Sampai jumpa lagi, Carween, Vice, PlayerName!",
  ui_story_5012_50120101_103_dialog_content = "Sampai jumpa!",
  ui_story_5012_50120101_104_dialog_content = "Hoi, kenapa kau tak mau mendengarkan pendapatku dulu, sih...?",
  ui_story_5012_50120201_1_dialog_content = "<color=#e8d9bb>Wuush, wuush...</color>",
  ui_story_5012_50120201_2_dialog_content = "Huff... Eh, apa kita benar-benar mau berjalan kaki mendaki <color=#FFB400>Winter Palace</color>?",
  ui_story_5012_50120201_3_dialog_content = "Seingatku, aku sudah menjelaskan bahwa kita tak bisa menggunakan jalur udara karena lokasi tempat ini terlalu tinggi.",
  ui_story_5012_50120201_4_dialog_content = "Yah, kurasa tempat ini juga terlalu tinggi untuk didaki dengan jalan kaki...",
  ui_story_5012_50120201_5_dialog_content = "Memangnya kita punya pilihan lain? Seandainya saja tadi tak ada yang berlambat-lambat...",
  ui_story_5012_50120201_6_dialog_content = "Mestinya tadi kita bisa menumpang kereta terakhir ke Northland.",
  ui_story_5012_50120201_7_dialog_content = "Berapa lama lagi kita akan sampai, Carleen?",
  ui_story_5012_50120201_8_dialog_content = "Sebentar lagi.",
  ui_story_5012_50120201_9_dialog_content = "Ayo, PlayerName, sebentar lagi kita akan sampai di istana!",
  ui_story_5012_50120201_10_dialog_content = "Maksudku, sebentar lagi kita akan sampai di perbatasan Northland.",
  ui_story_5012_50120201_11_dialog_content = "Apa?!",
  ui_story_5012_50120201_12_dialog_content = "<size=35><color=#e8d9bb>Klak, klak, klak...</color></size>",
  ui_story_5012_50120201_13_dialog_content = "Ya ampun. Aku setengah mati ingin dapat tumpangan sampai-sampai aku berhalusinasi melihat kereta.",
  ui_story_5012_50120201_14_dialog_content = "Sepertinya aku juga berhalusinasi seperti PlayerName.",
  ui_story_5012_50120201_15_dialog_content = "Itu bukan halusinasi, tapi juga bukan kereta.",
  ui_story_5012_50120201_16_dialog_content = "<color=#e8d9bb>*klak, klak, klak*</color>",
  ui_story_5012_50120201_17_dialog_content = "Oh, aku melihatnya! Apa itu kereta salju yang ditarik rusa kutub?",
  ui_story_5012_50120201_18_dialog_content = "Hoi! Tolong berhenti! Apa kami boleh menumpang...?",
  ui_story_5012_50120201_19_dialog_content = "<size=45><color=#e8d9bb>Klak, klak, klak...</color></size>",
  ui_story_5012_50120201_20_dialog_content = "Woah!",
  ui_story_5012_50120201_21_dialog_content = "<color=#e8d9bb>Ciit...</color>",
  ui_story_5012_50120201_22_dialog_content = "Hoi, jangan berdiri di tengah jalan!",
  ui_story_5012_50120201_23_dialog_content = "Nyaris saja! Kalau saja aku tak mengerem tepat waktu...",
  ui_story_5012_50120201_24_dialog_content = "Maaf, kami yang salah. Kau baik-baik saja?",
  ui_story_5012_50120201_25_dialog_content = "Aku baik-baik saja, tapi kalian ini sedang apa sih di sini?",
  ui_story_5012_50120201_26_dialog_content = "Sebentar lagi Tahun Baru. Kukira semua orang tinggal di rumah saja untuk bersiap-siap merayakannya!",
  ui_story_5012_50120201_27_dialog_content = "Ya, benar sekali! Kami diundang untuk merayakan Tahun Baru di Northland.",
  ui_story_5012_50120201_28_dialog_content = "Tapi, kami ketinggalan kereta terakhir, jadi...",
  ui_story_5012_50120201_29_dialog_content = "Huh, dilihat pakaian kalian, kalian pasti bukan orang sini.",
  ui_story_5012_50120201_30_dialog_content = "Tunggu, kalian bukan bandit atau penjahat, 'kan?",
  ui_story_5012_50120201_31_dialog_content = "Seingatku, dulu orang-orang Northland tak mudah berprasangka. Sepertinya sekarang mereka sudah jadi paranoid.",
  ui_story_5012_50120201_32_dialog_content = "Apa hanya perasaanku saja, atau memang barusan hawa terasa dingin... dan suaramu seperti... Queen Bethlehem?",
  ui_story_5012_50120201_33_dialog_content = "Aku tak mau memberitahukannya, tapi dulu sang Ratu pernah mengajariku.",
  ui_story_5012_50120201_34_dialog_content = "Dan memang Her Majestylah yang mengirimkan undangan untuk Perayaan Tahun Baru di Northland.",
  ui_story_5012_50120201_35_dialog_content = "Benar. Lihat, ini undangannya.",
  ui_story_5012_50120201_36_dialog_content = "Rupanya kalian orang-orang asing yang diundang sang Ratu! Kenapa tidak bilang dari tadi, sih?",
  ui_story_5012_50120201_37_dialog_content = "Tamu sang Ratu berarti juga tamu bagi <color=#FFB400>Lola</color>.",
  ui_story_5012_50120201_38_dialog_content = "Naiklah!",
  ui_story_5012_50120201_39_dialog_content = "Hah?",
  ui_story_5012_50120201_40_dialog_content = "Tujuan kalian sama denganku!",
  ui_story_5012_50120201_41_dialog_content = "Kecuali kalau kalian benar-benar mau berjalan kaki mendaki sampai ke istana.",
  ui_story_5012_50120201_42_dialog_content = "Terima kasih! Eh, kok tahu-tahu kau sudah naik ke kereta ini, PlayerName?",
  ui_story_5012_50120201_43_dialog_content = "Duduk tegak, kita berangkat!",
  ui_story_5012_50120201_44_dialog_content = "<color=#e8d9bb>Wuush, wuush...</color>",
  ui_story_5012_50120201_45_dialog_content = "Hatsyiii!",
  ui_story_5012_50120201_46_dialog_content = "Kau menggigil, PlayerName?",
  ui_story_5012_50120201_47_dialog_content = "Aku tak apa-apa, tapi aku merasa agak... Hatsyiii!",
  ui_story_5012_50120201_48_dialog_content = "Dingin...",
  ui_story_5012_50120201_49_dialog_content = "Sembilan dari sepuluh orang yang baru pertama kali berkunjung ke Northland memang tak tahan dengan suhu yang sangat rendah ini.",
  ui_story_5012_50120201_50_dialog_content = "Heeheehee! Tapi, aku punya sesuatu untuk mengatasinya!",
  ui_story_5012_50120201_51_dialog_content = "Yakin deh, kalian akan merasa hangat seperti api!",
  ui_story_5012_50120201_52_dialog_content = "Apa itu?",
  ui_story_5012_50120201_53_dialog_content = "Sangat mudah, gerakkan saja tubuh kalian, misalnya...",
  ui_story_5012_50120201_54_dialog_content = "Menarik kereta dengan rusa kutub!",
  ui_story_5012_50120201_55_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5012_50120201_56_dialog_content = "Jangan marah. Aku cuma bercanda.",
  ui_story_5012_50120201_57_dialog_content = "Suara yang kautimbulkan tadi mengerikan sekali.",
  ui_story_5012_50120201_58_dialog_content = "Bukan aku yang menimbulkan suara itu...",
  ui_story_5012_50120201_59_dialog_content = "<color=#e8d9bb>Duaar, gruduk!</color>",
  ui_story_5012_50120201_60_dialog_content = "Rusa kutub, berhenti!",
  ui_story_5012_50120201_61_dialog_content = "Hewan-hewan ini ketakutan... Awas!",
  ui_story_5012_50120201_62_dialog_content = "Hoi, jangan lari ke arah hutan, nanti kita bisa menabrak...",
  ui_story_5012_50120201_63_dialog_content = "<color=#e8d9bb>Bruk, plak, plak, plak!</color>",
  ui_story_5012_50120201_64_dialog_content = "Aduh...",
  ui_story_5012_50120201_65_dialog_content = "PlayerName, apa kau terluka?",
  ui_story_5012_50120201_66_dialog_content = "Aku baik-baik saja.",
  ui_story_5012_50120201_67_dialog_content = "Justru aku merasa jauh lebih hangat setelah jatuh terguling-guling.",
  ui_story_5012_50120201_68_dialog_content = "Tapi, mana rusa-rusa kutubnya?",
  ui_story_5012_50120201_69_dialog_content = "Oh, tidak, mereka lari kabur bersama keretanya!",
  ui_story_5012_50120201_70_dialog_content = "Aku sudah bersusah-payah menyiapkan kado, dan semuanya ada di dalam kereta itu...",
  ui_story_5012_50120201_71_dialog_content = "Apa memang kita ditakdirkan untuk mendaki ke Northland?",
  ui_story_5012_50120201_72_dialog_content = "Tapi, suara kencang apa itu? Guntur?",
  ui_story_5012_50120201_73_dialog_content = "Ya, mungkin saja itu guntur.",
  ui_story_5012_50120201_74_dialog_content = "Guntur saat hujan salju? Baru sekali ini aku mendengarnya.",
  ui_story_5012_50120201_75_dialog_content = "Her Majesty bilang, badai salju paling besar biasanya disertai guntur dan petir.",
  ui_story_5012_50120201_76_dialog_content = "<color=#e8d9bb>Duaaaar!</color>",
  ui_story_5012_50120201_77_dialog_content = "Lihat, salju mulai turun.",
  ui_story_5012_50120201_78_dialog_content = "Sepertinya kita akan menghadapi badai salju besar.",
  ui_story_5012_50120201_79_dialog_content = "Badai salju sama sekali bukan lelucon!",
  ui_story_5012_50120201_80_dialog_content = "Kalau tak mencari tempat berlindung, bisa-bisa kita jadi boneka salju sungguhan.",
  ui_story_5012_50120201_81_dialog_content = "Mestinya kita sudah dekat Pine Frost Valley. Seingatku, di sana ada pos jaga.",
  ui_story_5012_50120201_82_dialog_content = "Apa kau tahu jalan pintas ke sana, Lola?",
  ui_story_5012_50120201_83_dialog_content = "Kau bertanya kepada orang yang tepat! Ikuti aku!",
  ui_story_5012_50120201_84_dialog_content = "<color=#e8d9bb>Wuush, wuush!</color>",
  ui_story_5012_50120201_85_dialog_content = "Aduh...",
  ui_story_5012_50120201_86_dialog_content = "Ada apa?",
  ui_story_5012_50120201_87_dialog_content = "Bukan apa-apa, hanya ranting patah.",
  ui_story_5012_50120201_88_dialog_content = "Aku tak menyangka ternyata salju lembut bisa menghantam mukaku dengan sangat keras.",
  ui_story_5012_50120201_89_dialog_content = "Aku bahkan tak bisa melihat jalan di depanku...",
  ui_story_5012_50120201_90_dialog_content = "Badai saljunya baru saja mulai. Kita harus bergegas.",
  ui_story_5012_50120201_91_dialog_content = "Hatsyiii! Saking dinginnya, seluruh tubuhku sampai hampir mati rasa, Lola...",
  ui_story_5012_50120201_92_option_content = "Apa kita sudah sampai?",
  ui_story_5012_50120201_93_dialog_content = "Seharusnya sih sebentar lagi kelihatan.",
  ui_story_5012_50120201_94_dialog_content = "Mungkin terhalang jarak pandang yang terbatas.",
  ui_story_5012_50120201_95_dialog_content = "Semuanya, tetap waspada.",
  ui_story_5012_50120201_96_option_content = "Kau baik-baik saja?",
  ui_story_5012_50120201_97_dialog_content = "Tentu saja. Aku kan warga sini. Ini tak akan bisa membuatku takut.",
  ui_story_5012_50120201_98_dialog_content = "Aku tak boleh panik. Kalau tidak, kalian akan kena masalah besar.",
  ui_story_5012_50120201_99_dialog_content = "Uhuk... Baiklah. Kalau begitu, kupercayakan kepadamu, Lola yang tenang.",
  ui_story_5012_50120201_100_dialog_content = "Lihat, ada jejak kaki!",
  ui_story_5012_50120201_101_dialog_content = "Mungkin ini jejak kaki orang-orang yang menuju ke pos jaga itu, seperti kita.",
  ui_story_5012_50120201_102_dialog_content = "Kita bisa mengikuti jejak ini saja sampai ke sana!",
  ui_story_5012_50120201_103_dialog_content = "Tapi, bentuk dan jumlah jejak ini...",
  ui_story_5012_50120201_104_dialog_content = "Tampaknya mirip sekali dengan jejak kaki kita sendiri.",
  ui_story_5012_50120201_105_dialog_content = "Jejak kaki kita sendiri? Tapi, kita kan baru saja ke sana!",
  ui_story_5012_50120201_106_dialog_content = "Carleen, maksudmu...?",
  ui_story_5012_50120201_107_dialog_content = "Dari tadi kita hanya berputar-putar di dalam hutan.",
  ui_story_5012_50120201_108_dialog_content = "Apa?!",
  ui_story_5012_50120201_109_dialog_content = "Maaf, aku tak menyangka akan tersesat...",
  ui_story_5012_50120201_110_dialog_content = "Semua ini salahku. Maafkan aku.",
  ui_story_5012_50120201_111_dialog_content = "Jangan terlalu menyalahkan diri, Lola. Pasti ada jalan lain!",
  ui_story_5012_50120201_112_dialog_content = "Kalau begitu, bisakah kau berhenti mencengkeramku, PlayerName?",
  ui_story_5012_50120201_113_dialog_content = "Tanganmu dingin sekali dan aku jadi merasa sakit karenanya.",
  ui_story_5012_50120201_114_dialog_content = "Kenapa kau berbuat begitu kepada Lola, PlayerName?",
  ui_story_5012_50120201_115_dialog_content = "Bukan aku. Sumpah! Aku sama sekali tak menyentuhnya...",
  ui_story_5012_50120201_116_dialog_content = "Grrr!",
  ui_story_5012_50120201_117_dialog_content = "Lagi-lagi Eclipsite?! Kalian bahkan tak libur walau sudah musim salju?",
  ui_story_5012_50120201_118_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_5012_50120202_1_dialog_content = "Bukannya di Northland tak ada Eclipsite?",
  ui_story_5012_50120202_2_dialog_content = "Untuk menuju Northland, kita harus melewati Pine Frost Valley.",
  ui_story_5012_50120202_3_dialog_content = "Gaah!",
  ui_story_5012_50120202_4_dialog_content = "Rapid Torrent!",
  ui_story_5012_50120202_5_dialog_content = "*Meraung*",
  ui_story_5012_50120202_6_dialog_content = "Jangan coba-coba kabur! Bangunlah, Magical Blossom!",
  ui_story_5012_50120202_7_dialog_content = "Huft. Saat akhirnya aku bisa tidur siang di kasurku yang hangat dan empuk...",
  ui_story_5012_50120202_8_dialog_content = "Grrrr!",
  ui_story_5012_50120202_9_dialog_content = "Awas, Lola, di belakangmu!",
  ui_story_5012_50120202_10_dialog_content = "Ice Blossom!",
  ui_story_5012_50120202_11_dialog_content = "Trims!",
  ui_story_5012_50120202_12_dialog_content = "Sekarang bukan saatnya. Tetap fokus, jangan sembrono dalam pertempuran!",
  ui_story_5012_50120202_13_dialog_content = "*Meraung*",
  ui_story_5012_50120202_14_dialog_content = "Apa hanya perasaanku saja, atau memang jumlah Eclipsite yang menuju kemari bertambah banyak?",
  ui_story_5012_50120202_15_dialog_content = "Bagaimana situasinya, PlayerName?",
  ui_story_5012_50120202_16_dialog_content = "Aku merasakan ada banyak Eclipsite bergerombol menuju ke sini.",
  ui_story_5012_50120202_17_dialog_content = "Grrrr!",
  ui_story_5012_50120202_18_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_5012_50120202_19_dialog_content = "Kita tak bisa terus-terusan begini. Kita butuh solusi.",
  ui_story_5012_50120202_20_dialog_content = "Kenapa kau meringkuk begitu, PlayerName? Kau terkena serangan mereka?",
  ui_story_5012_50120202_21_dialog_content = "Para <color=#FFB400>kelinci</color> ini benar-benar menari, aku mencoba...",
  ui_story_5012_50120202_22_dialog_content = "Ini bukan saat yang tepat untuk itu!",
  ui_story_5012_50120202_23_dialog_content = "Tapi, kurasa mereka sedang berusaha memberi tahu kita sesuatu lewat gerakan mereka...",
  ui_story_5012_50120202_24_dialog_content = "Kelinci? Di sini? Jangan-jangan ada... <color=#FFB400>Novio</color>?",
  ui_story_5012_50120202_25_dialog_content = "Hei, mereka lari...",
  ui_story_5012_50120202_26_dialog_content = "Mungkin... Cepat, ikuti kelincinya!",
  ui_story_5012_50120202_27_dialog_content = "Grrr!",
  ui_story_5012_50120202_28_dialog_content = "Rapid Torrent!",
  ui_story_5012_50120202_29_dialog_content = "Mereka hanya kelinci, dan kita sudah beberapa kali berbelok... Kamu yakin yang kita lakukan ini sudah benar?",
  ui_story_5012_50120202_30_dialog_content = "Ini satu-satunya pilihan kita. Semoga saja memang benar itu dia.",
  ui_story_5012_50120202_31_dialog_content = "Awas, dari belakangmu!",
  ui_story_5012_50120202_32_dialog_content = "*Meraung*",
  ui_story_5012_50120202_33_dialog_content = "Ice Blossom—",
  ui_story_5012_50120202_X33_dialog_content = "Aduh...",
  ui_story_5012_50120202_34_dialog_content = "Carleen!",
  ui_story_5012_50120202_35_dialog_content = "Uhuk... Aku baik-baik saja, Vice. Lindungi PlayerName, aku akan melindungi bagian belakang!",
  ui_story_5012_50120202_36_dialog_content = "Jalannya... Untunglah, sebentar lagi kita akan sampai di Pine Frost Valley!",
  ui_story_5012_50120202_37_dialog_content = "Grrr!",
  ui_story_5012_50120202_38_dialog_content = "Ice Blossom!",
  ui_story_5012_50120202_39_dialog_content = "<color=#e8d9bb>Duar! Brak!</color>",
  ui_story_5012_50120202_40_dialog_content = "Gaah...",
  ui_story_5012_50120202_41_dialog_content = "Hatsyiii! Hawa dingin barusan itu apa? Hei, semua Eclipsite-nya kalah!",
  ui_story_5012_50120202_42_dialog_content = "Jadi, rupanya selama ini kau menyimpan tenagamu, Carleen?",
  ui_story_5012_50120202_43_dialog_content = "Tidak, bukan aku yang melakukannya...",
  ui_story_5012_50120202_X43_dialog_content = "Ini...",
  ui_story_5012_50120202_44_dialog_content = "Rupanya latihanmu belum banyak bertambah, Carleen.",
  ui_story_5012_50120202_45_dialog_content = "Yang Mulia?!",
  ui_story_5012_50120202_46_dialog_content = "(Aku tak pernah menyangka bisa melihat Carleen kebingungan seperti itu...)",
  ui_story_5012_50120202_47_dialog_content = "Yang Mulia! Novio! Huaaa... Kukira aku tak akan pernah melihat kalian lagi...",
  ui_story_5012_50120202_48_dialog_content = "Dan... Semua kado yang sudah kukumpulkan itu hilang...",
  ui_story_5012_50120202_49_dialog_content = "Oh, Lola... dasar cengeng...",
  ui_story_5012_50120202_50_dialog_content = "Mana gadis percaya diri yang dulu sangat ingin meninggalkan Northland untuk melihat dunia?",
  ui_story_5012_50120202_51_dialog_content = "Lola, coba lihat di belakang kereta. Apa itu barang-barangmu yang tadi hilang?",
  ui_story_5012_50120202_52_dialog_content = "Wow, Yang Mulia menemukannya! Hidup sang Ratu!",
  ui_story_5012_50120202_53_dialog_content = "Terima kasih atas bantuan Anda, Yang Mulia. Maafkan hamba yang payah ini... Uhuk...",
  ui_story_5012_50120202_54_dialog_content = "Novio, tolong obati luka Carleen.",
  ui_story_5012_50120202_55_dialog_content = "Baik.",
  ui_story_5012_50120202_56_dialog_content = "Maafkan aku, PlayerName.",
  ui_story_5012_50120202_57_dialog_content = "Padahal kau tamuku di Northland, tapi tetap saja nyawamu terancam. Kumohon maafkan aku.",
  ui_story_5012_50120202_58_dialog_content = "Ini, eee, tak apa-apa, sungguh...",
  ui_story_5012_50120202_59_dialog_content = "Kalau saja tadi kami tidak ketinggalan kereta, kalian tak perlu repot-repot datang kemari untuk menyelamatkan kami.",
  ui_story_5012_50120202_60_dialog_content = "Siapa wanita di belakangmu...?",
  ui_story_5012_50120202_61_dialog_content = "Salam, Yang Mulia, aku Vice. Hamba ingat kita pernah bertemu di Lumopolis.",
  ui_story_5012_50120202_62_dialog_content = "Ya, aku ingat.",
  ui_story_5012_50120202_63_dialog_content = "Tadinya kukira PlayerName akan pergi sendirian tanpa mengajak keluarganya.",
  ui_story_5012_50120202_64_dialog_content = "Tidak, tolong jangan berpikir begitu!",
  ui_story_5012_50120202_65_dialog_content = "Maaf, aku belum sempat memperkenalkan diri. Aku Novio, warga Northland.",
  ui_story_5012_50120202_66_dialog_content = "Silakan naik ke kereta, lalu kita berangkat...",
  ui_story_5012_50120202_67_dialog_content = "kembali ke Winter Palace.",
  ui_story_5012_50120301_1_dialog_content = "<color=#e8d9bb>Klak, klak, klak...</color>",
  ui_story_5012_50120301_2_dialog_content = "Yuuhuu, aku kembali, Northland!",
  ui_story_5012_50120301_3_dialog_content = "Padahal dulu kau tak sabar ingin pergi dari sini. Kukira kau tak akan pernah mau kembali kemari!",
  ui_story_5012_50120301_4_dialog_content = "Yah, kita kan memang perlu pergi ke dunia luar lalu pulang lagi! Benar begitu 'kan, Yang Mulia?",
  ui_story_5012_50120301_5_dialog_content = "Dalam kasusmu, kurasa benar begitu.",
  ui_story_5012_50120301_6_dialog_content = "Aku tak sabar ingin menyantap kue madu murni... Memikirkannya saja, aku sudah ngiler!",
  ui_story_5012_50120301_7_dialog_content = "Kue madu di tempat lain sama sekali tak enak. Aku menyesal tak membawanya lebih banyak.",
  ui_story_5012_50120301_8_dialog_content = "Jadi, selama ini kau bertualang, Lola? Kau pergi ke mana?",
  ui_story_5012_50120301_9_dialog_content = "Aku ke... ke... Zzzzz...",
  ui_story_5012_50120301_10_dialog_content = "Harap maklum saja, ya. Bocah ini memang bisa tidur di sembarang tempat.",
  ui_story_5012_50120301_11_dialog_content = "Sebenarnya itu hal yang mengagumkan.",
  ui_story_5012_50120301_12_dialog_content = "Oh? Apa kau sulit tidur, PlayerName?",
  ui_story_5012_50120301_13_option_content = "Ya",
  ui_story_5012_50120301_14_dialog_content = "Saat ada banyak hal yang kupikirkan, aku jadi sulit tidur.",
  ui_story_5012_50120301_15_dialog_content = "Hanya bisa berguling-guling saja sampai dini hari.",
  ui_story_5012_50120301_16_option_content = "Tidak",
  ui_story_5012_50120301_17_dialog_content = "Tidak juga...",
  ui_story_5012_50120301_18_dialog_content = "Tapi, saat ada banyak hal yang kupikirkan, aku jadi sulit tidur.",
  ui_story_5012_50120301_19_dialog_content = "Sepertinya masih ada hal yang perlu kauselesaikan.",
  ui_story_5012_50120301_20_dialog_content = "...",
  ui_story_5012_50120301_21_dialog_content = "Tapi, memikirkan masalah memang wajar bagi bocah seusiamu.",
  ui_story_5012_50120301_22_dialog_content = "Aku punya buku yang mungkin bisa bermanfaat.",
  ui_story_5012_50120301_23_dialog_content = "Jangan sungkan kalau mau membaca sedikit. Lagi pula...",
  ui_story_5012_50120301_24_dialog_content = "Perjalanan kita akan lama.",
  ui_story_5012_50120301_25_dialog_content = "Hah? Buku ini tampak tak asing...",
  ui_story_5012_50120301_X25_dialog_content = "Tapi, kenapa tak ada judulnya?",
  ui_story_5012_50120301_26_dialog_content = "Judulnya berbeda-beda bagi setiap orang yang sudah membacanya.",
  ui_story_5012_50120301_27_dialog_content = "Aku sangat ingin tahu judul apa yang akan kauberikan setelah selesai membacanya.",
  ui_story_5012_50120301_28_dialog_content = "Sungguh mendalam... Apa isi buku ini?",
  ui_story_5012_50120301_29_dialog_content = "Berbagai mantra yang mungkin bisa mengatasi masalahmu, misalnya...",
  ui_story_5012_50120301_30_dialog_content = "Dari mana asalku.",
  ui_story_5012_50120301_31_dialog_content = "Ke mana tujuanku.",
  ui_story_5012_50120301_32_dialog_content = "Siapa diriku sesungguhnya.",
  ui_story_5012_50120301_33_dialog_content = "Siapa aku...",
  ui_story_5012_50120301_34_dialog_content = "Siapa aku...",
  ui_story_5012_50120301_35_dialog_content = "Siapa...",
  ui_story_5012_50120301_36_dialog_content = "...",
  ui_story_5012_50120301_37_dialog_content = "<size=45>Siapa?!</size>",
  ui_story_5012_50120301_38_dialog_content = "Siapa kau?",
  ui_story_5012_50120301_39_dialog_content = "...",
  ui_story_5012_50120301_40_dialog_content = "Jangan melamun terus. Ambil senjatamu!",
  ui_story_5012_50120301_41_dialog_content = "Senjata?",
  ui_story_5012_50120301_42_dialog_content = "Para Eclipsite sudah menembus masuk ke <color=#FFB400>Eraveil</color>!",
  ui_story_5012_50120301_43_dialog_content = "Demi negeri kita...",
  ui_story_5012_50120301_44_dialog_content = "Ambil senjatamu!",
  ui_story_5012_50120401_1_dialog_content = "<size=45>Rarrr!</size>",
  ui_story_5012_50120401_2_dialog_content = "Aduh! Uhuk... Sial, aku tak punya kesempatan untuk menggunakan senjata ini...",
  ui_story_5012_50120401_3_dialog_content = "Huaa, huaa!",
  ui_story_5012_50120401_4_dialog_content = "Aku akan melawanmu dengan segenap kemampuanku!",
  ui_story_5012_50120401_5_dialog_content = "Tolong, kumohon! Aku sedang hamil... Kumohon...",
  ui_story_5012_50120401_6_dialog_content = "Kemari, tangani si tua bangka bodoh ini! Aduh...!",
  ui_story_5012_50120401_7_dialog_content = "...",
  ui_story_5012_50120401_8_dialog_content = "Kenapa? Kenapa jadi begini?",
  ui_story_5012_50120401_9_dialog_content = "Kalau saja aku bisa...",
  ui_story_5012_50120401_10_dialog_content = "Menggunakan Luminatics yang bisa membekukan segalanya...",
  ui_story_5012_50120401_11_dialog_content = "Apa-apaan aku ini? Aku bukan Aurorian. Tapi, memangnya aku bisa apa lagi?",
  ui_story_5012_50120401_12_dialog_content = "Kemampuan psikis! Aku masih punya kemampuan psikis! Tapi, apa gunanya...",
  ui_story_5012_50120401_13_dialog_content = "Biar kucoba...",
  ui_story_5012_50120401_14_option_content = "Tautkan pikiran!",
  ui_story_5012_50120401_15_dialog_content = "<anim type=Shake>&*%……@￥%...Rarrr!</anim>",
  ui_story_5012_50120401_16_dialog_content = "Barusan itu apa?",
  ui_story_5012_50120401_17_dialog_content = "Apa aku baru saja merasakan... pikiran Eclipsite!?",
  ui_story_5012_50120401_18_dialog_content = "Grrrr!",
  ui_story_5012_50120401_X18_dialog_content = "Lalu, apa kita bisa menggunakan senjata ini saja...?",
  ui_story_5012_50120401_19_dialog_content = "Dasar Eclipsite menjijikkan! Sampah!",
  ui_story_5012_50120401_20_dialog_content = "Kalian tak diterima di Eraveil! Pergi dan jangan kembali lagi!",
  ui_story_5012_50120401_21_dialog_content = "Rarrr! Grrrr!",
  ui_story_5012_50120401_22_dialog_content = "Hahahaha! Bukankah kenyataan membuatmu cukup kewalahan?",
  ui_story_5012_50120401_23_dialog_content = "Kau tak bisa lari ke mana pun.",
  ui_story_5012_50120401_24_dialog_content = "Siapa kau?",
  ui_story_5012_50120401_25_dialog_content = "Kenapa tidak kautanyakan itu kepada dirimu sendiri saja?",
  ui_story_5012_50120401_26_dialog_content = "Aku tahu siapa diriku!",
  ui_story_5012_50120401_27_dialog_content = "Kalau begitu, siapa namamu?",
  ui_story_5012_50120401_28_dialog_content = "Schummer!",
  ui_story_5012_50120401_29_dialog_content = "Tunggu, tidak... Kebetulan, aku ingat nama \"Schummer\".",
  ui_story_5012_50120401_30_dialog_content = "Aku bukan Schummer, aku bukan Schummer... Aku...",
  ui_story_5012_50120401_31_dialog_content = "<size=45>Siapa aku?</size>",
  ui_story_5012_50120401_32_dialog_content = "Tentu saja kau bukan Schummer. Schummer lebih memahami dirinya dibandingkan dirimu.",
  ui_story_5012_50120401_33_dialog_content = "Dia mendapatkan kekuatannya sudah sejak dulu, bahkan lebih dulu daripada aku.",
  ui_story_5012_50120401_34_dialog_content = "Dia bisa berbuat apa pun yang diinginkannya. Oh, aku sungguh iri kepadanya!",
  ui_story_5012_50120401_35_dialog_content = "Tak ada yang patut dibanggakan! Dia menjual kaum Caelestite, bahkan jiwanya sendiri!",
  ui_story_5012_50120401_36_dialog_content = "Schummer-lah yang tak mengenal dirinya sendiri.",
  ui_story_5012_50120401_37_dialog_content = "Bravo, bagus sekali!",
  ui_story_5012_50120401_38_dialog_content = "Seandainya saja jawaban jujur seperti itu bisa menyelamatkan kaummu...",
  ui_story_5012_50120401_39_dialog_content = "Huaa, huaa...",
  ui_story_5012_50120401_40_dialog_content = "Anakku!",
  ui_story_5012_50120401_41_dialog_content = "Selamatkan mereka, selamatkan mereka!",
  ui_story_5012_50120401_42_dialog_content = "Bagaimana aku bisa menyelamatkan semua orang dari kekejaman ini? Bagaimana...?",
  ui_story_5012_50120401_43_dialog_content = "Angkat dagumu.",
  ui_story_5012_50120401_44_dialog_content = "Jawaban yang kaucari ada tepat di depanmu, memintamu untuk meraihnya.",
  ui_story_5012_50120401_45_dialog_content = "Sangat menggiurkan, bahkan aku sendiri pun tak sanggup menahan diri...",
  ui_story_5012_50120401_46_dialog_content = "Apa itu <color=#FFB400>Seed</color>?",
  ui_story_5012_50120401_47_dialog_content = "Hei, ternyata kau tahu cukup banyak!",
  ui_story_5012_50120401_48_dialog_content = "Ya, sumber semua kekuatan, imbalan paling manis di dunia ini...",
  ui_story_5012_50120401_49_dialog_content = "Dengannya, kau bisa melindungi bayi yang menangis itu, menyelamatkan Eraveil dari kobaran api...",
  ui_story_5012_50120401_50_dialog_content = "Kau bahkan akan bisa menciptakan peradaban ideal sesuai keinginanmu, atau menghancurkan kerajaan mana pun yang menurutmu menjijikkan!",
  ui_story_5012_50120401_51_dialog_content = "Itu untuk Eclipsite, bukan untukku!",
  ui_story_5012_50120401_52_dialog_content = "Kau tak tahu apa yang baik untukmu! Semua orang di sekitarmu akan mati akibat keputusanmu!",
  ui_story_5012_50120401_53_dialog_content = "Tidakkah kau akan menyesalinya?",
  ui_story_5012_50120401_54_dialog_content = "Satu-satunya penyesalan adalah kalau aku sampai menelan Seed itu!",
  ui_story_5012_50120401_55_dialog_content = "Dan aku tak akan membiarkanmu menyakiti mereka lagi!",
  ui_story_5012_50120401_56_option_content = "Tautkan pikiran!",
  ui_story_5012_50120401_57_dialog_content = "Graaah!",
  ui_story_5012_50120401_58_dialog_content = "*Meraung*",
  ui_story_5012_50120401_59_dialog_content = "Mustahil? Apa ini perbuatanmu? Bagaimana bisa?",
  ui_story_5012_50120401_60_dialog_content = "Berhasil! Aku tak percaya aku bisa memanipulasi pikiran mereka untuk saling menyerang!",
  ui_story_5012_50120401_61_dialog_content = "Kau bisa mengendalikan Eclipsite? Ini jadi makin menarik!",
  ui_story_5012_50120401_62_dialog_content = "Jadi, sekali lagi, pertanyaannya adalah sebenarnya kau ini apa?",
  ui_story_5012_50120401_63_dialog_content = "Seorang Caelestite yang bisa mengendalikan Eclipsite... Atau Eclipsite dalam wujud Caelestite?",
  ui_story_5012_50120401_64_dialog_content = "Atau barangkali bukan dua-duanya.",
  ui_story_5012_50120401_65_dialog_content = "<size=45>Diam! Sudah, diamlah!</size>",
  ui_story_5012_50120401_66_option_content = "Meningkatkan kekuatan psikisku!",
  ui_story_5012_50120402_1_dialog_content = "Gahhh...",
  ui_story_5012_50120402_2_dialog_content = "Para Eclipsite itu sudah hampir selesai di sini...",
  ui_story_5012_50120402_3_dialog_content = "Teman-teman, ayo angkat senjata kita!",
  ui_story_5012_50120402_4_dialog_content = "Dan hantamkan pukulan terakhir kepada para monster itu!",
  ui_story_5012_50120402_5_dialog_content = "Ayo! Maju!",
  ui_story_5012_50120402_6_dialog_content = "Gaah... Graaah...",
  ui_story_5012_50120402_7_dialog_content = "Dan kau, pengkhianat, kau tak akan bisa kabur!",
  ui_story_5012_50120402_8_dialog_content = "Uhuk... Kau akan menyesalinya.",
  ui_story_5012_50120402_9_dialog_content = "Pusatkan seranganmu, ini yang terakhir!",
  ui_story_5012_50120402_10_dialog_content = "Makan nih pelurunya, mati sana!",
  ui_story_5012_50120402_11_dialog_content = "Oh... Aduh... Uhuk...",
  ui_story_5012_50120402_12_dialog_content = "Huh, kau melakukannya untuk melindungi orang-orang lemah di belakangmu...",
  ui_story_5012_50120402_13_dialog_content = "Tapi, tahukah kau bahwa aku memilih jadi seperti ini agar bisa melindungi kaumku?",
  ui_story_5012_50120402_14_dialog_content = "Kaummu pasti malu karenamu!",
  ui_story_5012_50120402_15_dialog_content = "Rupanya kau belum paham juga. Tanpa aku, tak seorang pun bisa melindungi kaumku.",
  ui_story_5012_50120402_16_dialog_content = "Mereka akan hancur.",
  ui_story_5012_50120402_17_dialog_content = "Coba lihatlah ke sana kalau kau tidak percaya. Eclipse telah datang. Mulai saat ini hingga seterusnya, hanya akan ada perang...",
  ui_story_5012_50120402_18_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5012_50120402_19_dialog_content = "Eraveil kalah.",
  ui_story_5012_50120402_20_dialog_content = "Ini tidak nyata! Aku hanya...",
  ui_story_5012_50120402_21_dialog_content = "Memang benar kau telah mengalahkanku. Tapi, tak ada satu pun yang akan berubah.",
  ui_story_5012_50120402_22_dialog_content = "Tetap saja kau tak bisa menyelamatkan Eraveil, tak bisa menyelamatkan orang-orang lemah di sekitarmu.",
  ui_story_5012_50120402_23_dialog_content = "Lagi pula, memangnya kau mau lari ke mana lagi?",
  ui_story_5012_50120402_24_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5012_50120402_25_dialog_content = "Eclipsite! Eclipsite yang tak terhitung banyaknya menyerang dari tempat lain!",
  ui_story_5012_50120402_26_dialog_content = "Kita kehabisan amunisi...",
  ui_story_5012_50120402_27_dialog_content = "Apa yang bisa kita lakukan, ke mana kita harus pergi?",
  ui_story_5012_50120402_28_dialog_content = "Aku tetap tak bisa menyelamatkan mereka walaupun sudah diberi kesempatan lagi?",
  ui_story_5012_50120402_29_dialog_content = "Apa yang kulakukan di sini?",
  ui_story_5012_50120402_30_dialog_content = "Bagaimana aku bisa ada di sini?",
  ui_story_5012_50120402_31_dialog_content = "Apa ada suatu tempat jauh di sana yang harus kudatangi?",
  ui_story_5012_50120402_32_dialog_content = "Siapa aku...?",
  ui_story_5012_50120501_1_dialog_content = "Ke mana tujuanku...?",
  ui_story_5012_50120501_2_dialog_content = "<size=30>PlayerName?</size>",
  ui_story_5012_50120501_3_dialog_content = "Siapa aku...",
  ui_story_5012_50120501_4_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_5012_50120501_5_dialog_content = "<color=#e8d9bb>Klak, klak, klak.</color>",
  ui_story_5012_50120501_6_dialog_content = "Vice?",
  ui_story_5012_50120501_7_dialog_content = "Akhirnya kau bangun, PlayerName.",
  ui_story_5012_50120501_8_dialog_content = "Bantu aku, cepat, Eraveil akan di...",
  ui_story_5012_50120501_9_dialog_content = "Kau ini bicara apa? Kita sedang berada di Northland.",
  ui_story_5012_50120501_10_dialog_content = "Northland?",
  ui_story_5012_50120501_11_dialog_content = "Ehem. Her Majesty sedang menatapmu, PlayerName.",
  ui_story_5012_50120501_12_dialog_content = "Oh... Yang Mulia!",
  ui_story_5012_50120501_13_dialog_content = "Kau pasti kelelahan.",
  ui_story_5012_50120501_14_dialog_content = "Maaf, tadi aku kehilangan fokus.",
  ui_story_5012_50120501_15_dialog_content = "Tadi aku sedang membaca buku... Hmm, mana bukunya, ya?",
  ui_story_5012_50120501_16_dialog_content = "Buku itu sudah memenuhi tugasnya setelah pembacanya menyadari perasaan mereka yang terpendam.",
  ui_story_5012_50120501_17_dialog_content = "...",
  ui_story_5012_50120501_18_dialog_content = "(Mungkin dia marah karena tadi aku tidak membacanya...)",
  ui_story_5012_50120501_19_dialog_content = "Hee, baru kali ini aku melihat orang yang lebih banyak tidur daripada aku.",
  ui_story_5012_50120501_20_dialog_content = "Apa mimpimu indah?",
  ui_story_5012_50120501_21_dialog_content = "Tidak bisa dibilang indah, sih... tapi rasanya sangat nyata.",
  ui_story_5012_50120501_X21_dialog_content = "Aku bermimpi... Aku bisa mengendalikan Eclipsite...",
  ui_story_5012_50120501_X22_dialog_content = "Apa? Mengendalikan Eclipsite...? Mimpimu gila sekali...",
  ui_story_5012_50120501_X23_dialog_content = "Aku belum pernah dengar ada Caelestite yang bisa mengendalikan Eclipsite.",
  ui_story_5012_50120501_22_dialog_content = "Pantas saja aku tak bisa membangunkanmu. Kau pasti terlena dalam dunia mimpi!",
  ui_story_5012_50120501_23_dialog_content = "Sayang sekali... Gara-gara mimpi kecilmu itu, kau melewatkan banyak pemandangan indah di sepanjang jalan.",
  ui_story_5012_50120501_24_dialog_content = "Tak apa, setidaknya PlayerName tak akan melewatkan...",
  ui_story_5012_50120501_25_dialog_content = "Winter Palace.",
  ui_story_5012_50120501_26_dialog_content = "Apa itu...?",
  ui_story_5012_50120501_27_dialog_content = "\"Mutiara Northland yang berkilau, istana yang gemerlap di bawah aurora.\"",
  ui_story_5012_50120501_28_dialog_content = "Aku sudah ratusan kali membaca tentangnya, tapi baru bisa percaya setelah melihatnya dengan mata kepalaku sendiri.",
  ui_story_5012_50120501_29_dialog_content = "Tak berubah sedikit pun.",
  ui_story_5012_50120501_30_dialog_content = "Rasanya aku jadi kembali ke tahun pertama kunjunganku ke Northland.",
  ui_story_5012_50120501_31_dialog_content = "Padahal kukira Lumopolis adalah tempat yang megah...",
  ui_story_5012_50120501_32_dialog_content = "Tapi, istana ini jauh lebih memukau.",
  ui_story_5012_50120501_33_dialog_content = "Berdiri di atas es dan salju tampak berkilauan. Rasanya seperti fantasi saja, hampir tidak nyata.",
  ui_story_5012_50120501_34_dialog_content = "Walau diselubungi alam yang dingin, istana ini memancarkan kehangatan.",
  ui_story_5012_50120501_35_dialog_content = "Pantas saja Northland disebut kerajaan dongeng. Pasti senang tinggal di sini.",
  ui_story_5012_50120501_36_dialog_content = "Tentu saja. Northland adalah tempat paling penuh kebahagiaan di dunia, tak ada tandingannya!",
  ui_story_5012_50120501_37_dialog_content = "Hmm, aku tak menyangka orang yang sangat ingin pergi dari Northland akan bilang begitu.",
  ui_story_5012_50120501_38_dialog_content = "Eh, aku bawa kado untuk semuanya! Kau juga dapat! Berhentilah menggodaku!",
  ui_story_5012_50120501_39_dialog_content = "Oh, apa aku boleh turun di sini, Yang Mulia?",
  ui_story_5012_50120501_40_dialog_content = "Aku punya banyak pernak-pernik yang ingin kubagikan kepada warga kota!",
  ui_story_5012_50120501_41_dialog_content = "Tentu saja.",
  ui_story_5012_50120501_42_dialog_content = "Bagaimana kalau sekalian saja kautemani PlayerName dan teman-temannya untuk melihat-lihat sekitar?",
  ui_story_5012_50120501_43_dialog_content = "Jadi, aku butuh bantuanmu!",
  ui_story_5012_50120501_44_dialog_content = "Setiap rumah di jalan ini dapat satu!",
  ui_story_5012_50120501_45_dialog_content = "Kukira kita mau berwisata, ternyata malah disuruh menjadi kurir.",
  ui_story_5012_50120501_46_dialog_content = "Ehem, berwisata adalah kegiatan basi.",
  ui_story_5012_50120501_47_dialog_content = "Dengan cara ini, kalian akan bisa lebih memahami cara hidup kami!",
  ui_story_5012_50120501_48_dialog_content = "Bagaimana kalau kita berlomba sedikit, Carleen?",
  ui_story_5012_50120501_49_dialog_content = "Lomba apa? Lomba siapa yang bisa mengantarkan lebih banyak kado?",
  ui_story_5012_50120501_50_dialog_content = "Kenapa sih kau malah memilih saat yang tidak tepat ini untuk mengajak berlomba, Vice?",
  ui_story_5012_50120501_51_dialog_content = "Yah, ini tak menarik untuk diperlombakan.",
  ui_story_5012_50120501_52_dialog_content = "Aku lebih hafal jalanan di sini, jadi kau boleh mulai satu menit lebih awal dariku.",
  ui_story_5012_50120501_53_dialog_content = "Kau benar-benar mau membuat ini jadi lomba?",
  ui_story_5012_50120501_54_dialog_content = "Tak usah, kita bisa mulai serentak!",
  ui_story_5012_50120501_55_dialog_content = "Baiklah, tapi jangan salahkan aku kalau kau kalah.",
  ui_story_5012_50120501_56_dialog_content = "Kau ke arah jalan sana, aku akan ke arah jalan ini.",
  ui_story_5012_50120501_57_dialog_content = "Kita bertemu lagi di alun-alun di ujung jalan.",
  ui_story_5012_50120501_58_dialog_content = "Ingat, beri tahu orang-orang bahwa kado itu dariku, Lola...!",
  ui_story_5012_50120501_59_dialog_content = "Oh, aku juga tak boleh sampai tertinggal!",
  ui_story_5012_50120501_60_dialog_content = "Kuserahkan padamu untuk mengantarkan semuanya, PlayerName!",
  ui_story_5012_50120501_61_dialog_content = "Aku susah payah mengangkutnya dari Umbraton, jadi tolong hati-hati, ya!",
  ui_story_5012_50120501_62_dialog_content = "Ini dari Umbraton? Coba kulihat...",
  ui_story_5012_50120501_63_dialog_content = "Bandul kalung gurita, lonceng berbentuk anjing, helm macan tutul, lukisan kupu-kupu... Sungguh koleksi yang bagus.",
  ui_story_5012_50120501_64_dialog_content = "Kau juga punya boneka windelion dan lampion dandelion?",
  ui_story_5012_50120501_65_dialog_content = "Bukannya ini mainan tradisional kaum Caelestite?",
  ui_story_5012_50120501_66_dialog_content = "Kata orang, kita bisa beli apa saja di Umbraton. Sepertinya memang benar begitu.",
  ui_story_5012_50120501_67_dialog_content = "Anu, kau tak perlu mengawalku berkeliling... Sejujurnya, aku jadi malu.",
  ui_story_5012_50120501_68_dialog_content = "Tapi, kau ini tamu kehormatan Her Majesty. Tentu saja aku harus mengawalmu.",
  ui_story_5012_50120501_69_dialog_content = "Yah, baiklah... Tunggu, kau tahu bahwa boneka dan lampion itu adalah barang khas kaum Caelestite?",
  ui_story_5012_50120501_70_dialog_content = "Northland dan Eraveil sudah lama menjalin hubungan baik. Tidak heran kalau aku tahu tentang hal-hal seperti itu.",
  ui_story_5012_50120501_71_dialog_content = "Lagi pula, pernak-pernik Caelestite ini cocok untuk menghias pohon kelip kami.",
  ui_story_5012_50120501_72_dialog_content = "Pohon kelip? Maksudmu pepohonan di halaman setiap rumah itu?",
  ui_story_5012_50120501_73_dialog_content = "Kau sangat cermat. Itu pohon Snow Spruce, varietas pohon yang paling umum tumbuh di Northland.",
  ui_story_5012_50120501_74_dialog_content = "Snow Spruce juga adalah bahan baku untuk sebagian besar rumah dan furnitur, dan karenanya melambangkan rumah dan keluarga.",
  ui_story_5012_50120501_75_dialog_content = "Pada Tahun Baru, setiap rumah akan memasang pohon yang bagus bentuknya...",
  ui_story_5012_50120501_76_dialog_content = "Setelah dipangkas di sana-sini dan dihias, jadilah pohon kelip.",
  ui_story_5012_50120501_77_dialog_content = "Memang, pohon kelip membuat suasana jadi makin meriah.",
  ui_story_5012_50120501_78_dialog_content = "Tn. Novio? Rupanya kau datang! Selamat Tahun Baru!",
  ui_story_5012_50120501_79_dialog_content = "Terima kasih. Selamat Tahun Baru juga untukmu. Bagaimana kabar keluargamu?",
  ui_story_5012_50120501_80_dialog_content = "Sebenarnya, sekarang mereka sedang bersembunyi dariku.",
  ui_story_5012_50120501_81_dialog_content = "Kalau aku tak salah, mungkin mereka sedang membungkus kado untukmu.",
  ui_story_5012_50120501_82_dialog_content = "Haha, setiap tahun selalu begitu. Mereka selalu mencari-cari alasan untuk diam-diam mencari kado tanpa sepengetahuanku.",
  ui_story_5012_50120501_83_dialog_content = "Kalau begitu, berarti aku juga bisa membungkus kado untuk mereka saat mereka pergi.",
  ui_story_5012_50120501_84_dialog_content = "Oh, ini ada sesuatu untukmu. Selamat Tahun Baru!",
  ui_story_5012_50120501_85_dialog_content = "Boneka windelion?",
  ui_story_5012_50120501_86_dialog_content = "Semasa kecil, kami biasa menggantung boneka ini. Oh, sungguh aku merindukannya!",
  ui_story_5012_50120501_87_dialog_content = "Akan kupasang di pohon sekarang juga. Terima kasih!",
  ui_story_5012_50120501_88_dialog_content = "Aneh... Kenapa mereka menggantung lampion tapi tidak menyalakannya?",
  ui_story_5012_50120501_89_dialog_content = "Karena mereka masih menunggu.",
  ui_story_5012_50120501_90_dialog_content = "Menunggu apa...?",
  ui_story_5012_50120501_91_dialog_content = "Hari ini adalah Tahun Baru Eve, jadi mereka menunggu sampai waktu yang tepat.",
  ui_story_5012_50120501_92_dialog_content = "Mereka akan menyalakan semua lampion dan api unggun saat fajar menyingsing.",
  ui_story_5012_50120501_93_dialog_content = "Bersamaan dengan <color=#FFB400>obor</color> yang selamanya menerangi kita di tepi laut.",
  ui_story_5012_50120501_94_dialog_content = "Obor di tepi laut? Apa itu?",
  ui_story_5012_50120501_95_dialog_content = "Soal itu, nanti kau juga akan tahu.",
  ui_story_5012_50120501_96_dialog_content = "Huff... Eh, kenapa kau masih di sini?",
  ui_story_5012_50120501_97_dialog_content = "Kami semua sudah menyelesaikan rute kami!",
  ui_story_5012_50120501_98_dialog_content = "Jadi, siapa yang menang?",
  ui_story_5012_50120501_99_dialog_content = "Kami bertiga mencapai garis akhir bersamaan.",
  ui_story_5012_50120501_100_dialog_content = "Jadi, kami memutuskan bahwa yang akan jadi pemenang adalah yang paling pertama menemukan PlayerName!",
  ui_story_5012_50120501_101_dialog_content = "Hah, kurasa akulah pemenangnya!",
  ui_story_5012_50120501_102_dialog_content = "Ah. Aku tak suka kalah saing...",
  ui_story_5012_50120501_103_dialog_content = "Aku tahu tempat bagus di dekat sini untuk bermain ski. Nanti kita lihat saja siapa yang paling hebat.",
  ui_story_5012_50120501_104_dialog_content = "Ha, sekarang siapa yang suka bersaing, coba?",
  ui_story_5012_50120501_105_dialog_content = "...",
  ui_story_5012_50120501_106_dialog_content = "Novio! Ayo, semuanya, Novio sudah datang!",
  ui_story_5012_50120501_107_dialog_content = "Kita berlatih menyanyi nanti saja. Ayo kita dengarkan cerita dari Novio!",
  ui_story_5012_50120501_108_dialog_content = "Baiklah, Waktunya Dongeng lagi!",
  ui_story_5012_50120501_109_dialog_content = "Woah, kita diserbu kerumunan anak kecil!",
  ui_story_5012_50120501_110_dialog_content = "Hei, jangan libatkan aku! Aku sudah berkali-kali mendengar kisahnya!",
  ui_story_5012_50120501_111_dialog_content = "Anak-anak, hari ini ada tamu sangat penting yang harus kutemui.",
  ui_story_5012_50120501_112_dialog_content = "Tapi, dari tadi kami sudah menunggu saat ini...",
  ui_story_5012_50120501_113_dialog_content = "Iya! Ayolah! Ini demi pohon berkilau yang sudah kita hias dengan cantik!",
  ui_story_5012_50120501_114_dialog_content = "Dan kami juga sudah berlatih menyanyi dengan sungguh-sungguh...",
  ui_story_5012_50120501_115_dialog_content = "Tak usah mengkhawatirkanku, Novio. Aku juga ingin mendengarmu bercerita.",
  ui_story_5012_50120501_116_dialog_content = "Yah, karena PlayerName yang meminta...",
  ui_story_5012_50120501_117_dialog_content = "Baiklah! Terima kasih, PlayerName!",
  ui_story_5012_50120501_118_dialog_content = "Coba kuingat-ingat dulu, terakhir kali ceritaku sampai mana, ya...?",
  ui_story_5012_50120501_119_dialog_content = "Nah, jadi setiap penguasa di Northland harus meninggalkan banyak hal agar bisa menjadi pemimpin sejati.",
  ui_story_5012_50120501_120_dialog_content = "Mereka meninggalkan hal-hal yang paling berharga bagi mereka...",
  ui_story_5012_50120501_121_dialog_content = "Mereka meninggalkan nama yang sudah disematkan kepada mereka sejak lahir.",
  ui_story_5012_50120501_122_dialog_content = "Mereka meninggalkan segalanya, dan mengabdikan seluruh hidup demi Northland, selamanya.",
  ui_story_5012_50120501_123_dialog_content = "Hanya dengan cara itulah mereka bisa mendapatkan kekuatan untuk mempertahankan Northland.",
  ui_story_5012_50120501_124_dialog_content = "Sedangkan Queen Bethlehem kita saat ini...",
  ui_story_5012_50120501_125_dialog_content = "Beliau berpikiran terbuka, tidak seperti para pemimpin lain dalam sejarah kita.",
  ui_story_5012_50120501_126_dialog_content = "Tapi, bahkan beliau pun harus menjalani metamorfosis ini.",
  ui_story_5012_50120501_127_dialog_content = "Saat itu...",
  ui_story_5012_50120601_1_dialog_content = "Saat itu, Her Majesty menyuruhku berlatih keras tanpa ampun.",
  ui_story_5012_50120601_2_dialog_content = "Beliau mengajariku banyak hal. Beliau punya rasa keadilan dan keteguhan hati yang sangat penting bagi seorang pemimpin hebat.",
  ui_story_5012_50120601_3_dialog_content = "Dia mengajariku cara mengayunkan pedang dan memegang tongkat kerajaan.",
  ui_story_5012_50120601_4_dialog_content = "Tapi, sebaliknya, aku tak bisa benar-benar mengenalnya.",
  ui_story_5012_50120601_5_dialog_content = "Carleen...",
  ui_story_5012_50120601_6_dialog_content = "Dari sudut pandang sejarawan, itu juga pertama kalinya aku melihat sang Ratu.",
  ui_story_5012_50120601_7_dialog_content = "Di Northland hanya ada sedikit buku, dan dokumen sejarah sangatlah langka.",
  ui_story_5012_50120601_8_dialog_content = "Selama tinggal di Northland, aku hanya bisa mengandalkan cerita lisan dan imajinasiku sendiri saja untuk mereka-reka masa lalu.",
  ui_story_5012_50120601_9_dialog_content = "Cerita lisan?",
  ui_story_5012_50120601_10_dialog_content = "Jangan bilang...",
  ui_story_5012_50120601_11_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_5012_50120601_12_dialog_content = "Silakan masuk.",
  ui_story_5012_50120601_13_dialog_content = "Salam dari musim dingin, PlayerName.",
  ui_story_5012_50120601_14_dialog_content = "Tepat waktu.",
  ui_story_5012_50120601_15_dialog_content = "Kau mau istirahat sekarang?",
  ui_story_5012_50120601_16_dialog_content = "Belum.",
  ui_story_5012_50120601_17_dialog_content = "Sepertinya kau belum capek. Caelestite memang berbeda.",
  ui_story_5012_50120601_18_dialog_content = "Tidak, kau salah paham.",
  ui_story_5012_50120601_19_dialog_content = "Dulu, pada saat-saat seperti ini, aku selalu menghabiskan waktu sendirian di dalam Colossus.",
  ui_story_5012_50120601_20_dialog_content = "Biasanya aku tidur sepanjang malam.",
  ui_story_5012_50120601_21_dialog_content = "Tapi, karena ini di Northland, aku tak ingin hari ini berakhir begitu cepat.",
  ui_story_5012_50120601_22_dialog_content = "Oh, begitu. Aku merasa sangat terhormat bisa menjadi bagian dari hari ini untukmu.",
  ui_story_5012_50120601_23_dialog_content = "Apa kau mau mengikuti acara pamungkas untuk merayakan Tahun Baru?",
  ui_story_5012_50120601_24_dialog_content = "Apa itu?",
  ui_story_5012_50120601_25_dialog_content = "Menurut kalender Northland, hari ini adalah hari terakhir dalam Tahun Baru, sekaligus hari yang sangat istimewa.",
  ui_story_5012_50120601_26_dialog_content = "Hari ini adalah <color=#FFB400>Polar Night</color>.",
  ui_story_5012_50120601_27_dialog_content = "Polar Night?",
  ui_story_5012_50120601_28_dialog_content = "Oh, Winter Palace dibangun dengan bahan khusus sehingga akan selalu bersinar, bahkan tanpa terkena sumber cahaya yang kuat.",
  ui_story_5012_50120601_29_dialog_content = "Itu sebabnya selama ini kau tak pernah menyadari keanehan itu.",
  ui_story_5012_50120601_30_dialog_content = "Orang-orang Northland punya kebiasaan berjaga sepanjang malam untuk menyaksikan matahari terbit untuk pertama kalinya saat tahun baru.",
  ui_story_5012_50120601_31_dialog_content = "Penantian itu juga melambangkan bagaimana kita bertahan dalam kegelapan dan kemudian menyongsong cahaya.",
  ui_story_5012_50120601_32_dialog_content = "Kedengarannya sangat menakjubkan.",
  ui_story_5012_50120601_33_dialog_content = "Kalau kau tertarik, aku bisa mengajakmu ke <color=#FFB400>Lake Mirror</color>.",
  ui_story_5012_50120601_34_dialog_content = "Lake Mirror? Bukannya di sana dingin sekali?",
  ui_story_5012_50120601_35_dialog_content = "Her Majesty menyuruhku mengingatkanmu agar bersiap-siap sebagaimana mestinya.",
  ui_story_5012_50120601_36_dialog_content = "Maksudmu, kau kemari atas perintah dari sang Ratu?",
  ui_story_5012_50120601_37_dialog_content = "Ya, Her Majesty memang menyuruhku. Kalau tidak, aku pasti tak akan mengganggumu.",
  ui_story_5012_50120601_38_dialog_content = "Kalau begitu...",
  ui_story_5012_50120601_39_dialog_content = "...",
  ui_story_5012_50120601_40_dialog_content = "Oke, oke, aku paham, kok.",
  ui_story_5012_50120601_41_dialog_content = "Mari, ikuti aku.",
  ui_story_5012_50120601_42_dialog_content = "<color=#e8d9bb>Wuuss...</color>",
  ui_story_5012_50120601_43_dialog_content = "Akhirnya sampai juga.",
  ui_story_5012_50120601_44_dialog_content = "Kita tunggu dulu di sini sebentar. Sebentar lagi Her Majesty akan kemari.",
  ui_story_5012_50120601_45_dialog_content = "Tentu saja, aku juga bisa menemanimu melihat-lihat sekitar danau.",
  ui_story_5012_50120601_46_dialog_content = "Lake Mirror memang seperti namanya. Lihat, pantulan airnya jernih sekali.",
  ui_story_5012_50120601_47_dialog_content = "Bukan itu saja, danau ini juga adalah cermin dua sisi: satu untuk menyongsong masa depan, satu lagi untuk menyimpan masa lalu.",
  ui_story_5012_50120601_48_dialog_content = "Kalau kaupandangi permukaannya, danau ini akan menerangimu.",
  ui_story_5012_50120601_49_dialog_content = "Menerangiku...",
  ui_story_5012_50120601_50_dialog_content = "...",
  ui_story_5012_50120601_51_dialog_content = "...",
  ui_story_5012_50120601_52_dialog_content = "Ayo, cepat susul aku!",
  ui_story_5012_50120601_53_dialog_content = "Sedikit lagi, lalu kita bisa membeli hiasan pohon kelip dari karavan!",
  ui_story_5012_50120601_54_dialog_content = "Apa?",
  ui_story_5012_50120601_55_dialog_content = "Apa kau memanggilku?",
  ui_story_5012_50120601_56_dialog_content = "Ya! Tapi, tolong, pelan-pelan saja, <color=#FFB400>Shaya</color>, Yang Mulia.",
  ui_story_5012_50120601_57_dialog_content = "Siapa orang asing yang berdiri bengong dan kebingungan di sampingmu itu?",
  ui_story_5012_50120601_58_dialog_content = "Maksudmu, aku?",
  ui_story_5012_50120601_59_dialog_content = "Kali ini, iya. Kau seorang Caelestite?!",
  ui_story_5012_50120601_60_dialog_content = "Sungguh cermat! Sebentar...",
  ui_story_5012_50120601_61_dialog_content = "Ini bukan Northland yang barusan kulihat.",
  ui_story_5012_50120601_62_dialog_content = "Apakah gadis kecil yang kulihat ini...?",
  ui_story_5012_50120601_63_dialog_content = "Dugaanmu tepat, PlayerName.",
  ui_story_5012_50120601_64_dialog_content = "Itu Queen Bethlehem saat masih kecil, walau saat itu dia dikenal dengan nama <color=#FFB400>Shaya</color>.",
  ui_story_5012_50120601_65_dialog_content = "Ayo, cepat!",
  ui_story_5012_50120601_66_dialog_content = "Aku sudah dapat hiasannya, tapi kita harus sudah selesai menghias pohon kelipnya sebelum matahari terbenam!",
  ui_story_5012_50120601_67_dialog_content = "Kalau kau mau berdiri saja di sana, aku pergi saja!",
  ui_story_5012_50120601_68_dialog_content = "Ada apa? Ada yang bisa memberitahuku?",
  ui_story_5012_50120601_69_dialog_content = "Oh, tidak, apa itu?",
  ui_story_5012_50120601_70_dialog_content = "Tolong!",
  ui_story_5012_50120601_71_dialog_content = "Apa yang terjadi?",
  ui_story_5012_50120601_72_dialog_content = "Oh, tidak...",
  ui_story_5012_50120601_73_dialog_content = "<size=50>Rarrr!</size>",
  ui_story_5012_50120601_74_dialog_content = "Eclipsite? Di sini?",
  ui_story_5012_50120601_75_dialog_content = "Novio, Caelestite, ayo kita periksa!",
  ui_story_5012_50120602_1_dialog_content = "Heh, heh...",
  ui_story_5012_50120602_2_dialog_content = "Aku tak percaya Eclipsite-nya setinggi itu!",
  ui_story_5012_50120602_3_dialog_content = "Aku bahkan sempat ragu saat menghunus pedangku.",
  ui_story_5012_50120602_4_dialog_content = "Bagus sekali, Yang Mulia.",
  ui_story_5012_50120602_5_dialog_content = "Begitukah? Apa aku sudah kelihatan seperti orang Northland yang pemberani, Novio?",
  ui_story_5012_50120602_6_dialog_content = "Tentu saja!",
  ui_story_5012_50120602_7_dialog_content = "Makhluk jelek dan menjijikkan itu memang harusnya tak ada di sini.",
  ui_story_5012_50120602_8_dialog_content = "Kau sudah menyelamatkan seluruh jalan ini.",
  ui_story_5012_50120602_9_dialog_content = "Terima kasih juga atas bantuanmu, PlayerName.",
  ui_story_5012_50120602_10_dialog_content = "Semoga kemunculan mereka yang tak terduga itu tak membuatmu takut.",
  ui_story_5012_50120602_11_dialog_content = "Aku tidak takut. Lagi pula, aku hanya melakukan yang kubisa.",
  ui_story_5012_50120602_12_dialog_content = "Tolong, jujurlah kepadaku, Novio.",
  ui_story_5012_50120602_13_dialog_content = "Kenapa tiba-tiba ada Eclipsite di Northland?",
  ui_story_5012_50120602_14_dialog_content = "Mereka tak butuh alasan selain diperintah oleh seseorang.",
  ui_story_5012_50120602_15_dialog_content = "Tidak, bukan begitu. Dibandingkan aku, kau pasti lebih tahu alasannya!",
  ui_story_5012_50120602_16_dialog_content = "Northland butuh pemimpin, dan hanya pemimpin itulah yang bisa menggunakan <color=#FFB400>Sanctuary</color> untuk melindungi Northland.",
  ui_story_5012_50120602_17_dialog_content = "Putri Shaya...",
  ui_story_5012_50120602_18_dialog_content = "Itu... Itu Lady Shaya...",
  ui_story_5012_50120602_19_dialog_content = "Demi Utara! Terima kasih sudah menyelamatkan kami, Lady Shaya...",
  ui_story_5012_50120602_20_dialog_content = "Saat Lady Shaya naik takhta, kita pasti akan bisa kembali hidup damai...",
  ui_story_5012_50120602_21_dialog_content = "Takhta? Yang benar saja!",
  ui_story_5012_50120602_22_dialog_content = "Bocah seperti dia tak pantas duduk di takhta kerajaan!",
  ui_story_5012_50120602_23_dialog_content = "Mana mungkin seorang bocah ingusan bisa menanggung kekuatan dan tanggung jawab <color=#FFB400>Spark</color>?",
  ui_story_5012_50120602_24_dialog_content = "Tapi, itu satu-satunya cara... Iya, 'kan?",
  ui_story_5012_50120602_25_dialog_content = "Coba lihat, <color=#FFB400>Beacon</color> yang selama ini selalu menyala kini padam... Northland tak lagi aman.",
  ui_story_5012_50120602_26_dialog_content = "Kalau Lady Shaya tak mewarisi Spark, apa kalian semua mau meringkuk di dalam rumah saja seumur hidup?",
  ui_story_5012_50120602_27_dialog_content = "Tak usah dengarkan omongan mereka, Lady Shaya. Kau hanya perlu mendengarkan kata hatimu sendiri...",
  ui_story_5012_50120602_28_dialog_content = "Aku paham, Novio... Tak usah diributkan lagi.",
  ui_story_5012_50120602_29_dialog_content = "Ayo, kita harus bergegas ke Lake Mirror.",
  ui_story_5012_50120602_30_dialog_content = "Kebetulan kita juga membawa benda itu... Setuju, tidak?",
  ui_story_5012_50120602_31_dialog_content = "Kau... telah mengambil keputusan.",
  ui_story_5012_50120602_32_dialog_content = "Ayo, kita berangkat.",
  ui_story_5012_50120602_33_dialog_content = "Tahu, tidak... Kadang Shaya terlihat tak lebih dari anak kecil biasa...",
  ui_story_5012_50120602_34_dialog_content = "Sebaiknya kau juga ikut, Lord PlayerName.",
  ui_story_5012_50120602_35_dialog_content = "Aku yakin kau pasti masih ragu, dan dengan senang hati aku akan mengatasinya.",
  ui_story_5012_50120602_36_dialog_content = "Sayangnya, setelah melihat satu Eclipsite... Bisa dipastikan ada lebih banyak Eclipsite yang berhasil menerobos masuk ke Northland.",
  ui_story_5012_50120602_37_dialog_content = "Kita semua harus tetap fokus dan lebih waspada.",
  ui_story_5012_50120602_38_dialog_content = "Aku lega mendengarmu berkata begitu.",
  ui_story_5012_50120602_39_dialog_content = "Aku yakin nanti kita akan membutuhkan kemampuanmu.",
  ui_story_5012_50120702_1_dialog_content = "<size=45>Groooaaar!!!</size>",
  ui_story_5012_50120702_2_dialog_content = "Winter Force...",
  ui_story_5012_50120702_3_dialog_content = "Graah...",
  ui_story_5012_50120702_4_option_content = "Forced Control",
  ui_story_5012_50120702_5_dialog_content = "Untuk sementara ini, kita bisa tenang. Sepertinya yang tadi itu adalah Eclipsite terakhir di dekat Lake Mirror.",
  ui_story_5012_50120702_6_dialog_content = "Kita mungkin memang berhasil membasmi para Eclipsite di hadapan kita, tapi aku yakin masih ada banyak lagi yang belum terlihat oleh kita, mengacau di tengah-tengah warga kita...",
  ui_story_5012_50120702_7_dialog_content = "Kita hampir kehabisan waktu.",
  ui_story_5012_50120702_8_dialog_content = "Apa pun itu... Kau sudah banyak membantu Northland, Caelestite.",
  ui_story_5012_50120702_9_dialog_content = "Sebenarnya, kurasa aku harus menyampaikan terima kasihku menurut tradisi Northland, tapi saat ini ada urusan lebih mendesak yang harus kutangani.",
  ui_story_5012_50120702_10_dialog_content = "Maka... Kupercayakan urusan ini kepada Novio!",
  ui_story_5012_50120702_11_dialog_content = "Ah, Putri Shaya... Kenapa malu-malu?",
  ui_story_5012_50120702_12_dialog_content = "...",
  ui_story_5012_50120702_13_dialog_content = "*Tertawa kecil* Kalau begitu, silakan, Lady Shaya. Masih banyak yang harus kubahas dengan Lord PlayerName.",
  ui_story_5012_50120702_14_dialog_content = "Tapi, sebelum kau pergi... Izinkan aku bicara sedikit lagi.",
  ui_story_5012_50120702_15_dialog_content = "Kuhargai setiap pilihanmu. Apa pun keputusannya, kau bisa dan akan membuat Northland berjaya.",
  ui_story_5012_50120702_16_dialog_content = "Jadi, tolong, jangan memaksa diri untuk melakukan hal yang nantinya akan kausesali...",
  ui_story_5012_50120702_17_dialog_content = "Kadang-kadang kau bisa jadi sangat ragu-ragu, Novio!",
  ui_story_5012_50120702_18_dialog_content = "Saat ini, aku tak perlu mengambil keputusan apa pun.",
  ui_story_5012_50120702_19_dialog_content = "Bisa tolong jelaskan apa yang sudah terjadi sejauh ini, Novio? Kalau tak keberatan, jelaskan dari awal...",
  ui_story_5012_50120702_20_dialog_content = "Lalu, kenapa kita ke Lake Mirror?",
  ui_story_5012_50120702_21_dialog_content = "Kau tak akan menyuruhku melihat ke dalam cermin lagi, 'kan...?",
  ui_story_5012_50120702_22_dialog_content = "Ini memang seperti apa yang kau lihat, PlayerName. Yang kau lihat itu adalah masa lalu Queen Bethlehem sebelum berhasil menduduki takhta Northland.",
  ui_story_5012_50120702_23_dialog_content = "Saat tiba waktunya pergantian pemimpin, kekuatan <color=#FFB400>Spark</color> terhenti untuk sementara waktu.",
  ui_story_5012_50120702_24_dialog_content = "Saat itulah Northland jadi sangat rentan, dan kerajaan ini hanya bisa mengandalkan perlindungan dari para penjaga di Pine Frost Valley.",
  ui_story_5012_50120702_25_dialog_content = "Jadi, para Eclipsite yang tadi itu... Mereka menyerang Northland dengan memanfaatkan celah waktu saat Northland tak punya perlindungan?",
  ui_story_5012_50120702_26_dialog_content = "Benar... Walau mereka kelihatan tak berotak, sepertinya mereka menyadari adanya celah waktu itu di kerajaan kami.",
  ui_story_5012_50120702_27_dialog_content = "Sebelum penerus takhta akhirnya muncul, Northland akan terus dirundung ketakutan dan bahaya.",
  ui_story_5012_50120702_28_dialog_content = "Selain itu, kekuatan Spark juga hanya akan mengabdikan diri kepada Northland, bukan kepada orang tertentu.",
  ui_story_5012_50120702_29_dialog_content = "Agar bisa mewarisi kekuatan Spark, calon penerus harus terlebih dulu sepenuhnya meninggalkan rasa cinta diri, dan mengabdikan seluruh hati dan jiwanya demi melindungi seluruh Northland...",
  ui_story_5012_50120702_30_dialog_content = "Kurasa Lady Bethlehem sudah memenuhi syarat itu.",
  ui_story_5012_50120702_31_dialog_content = "Aku setuju. Lady Bethlehem yang kaulihat di hadapanmu sekarang ini adalah orang yang paling pantas mewarisi Spark.",
  ui_story_5012_50120702_32_dialog_content = "Semasa kecil, Her Majesty tak pernah punya teman sebaya. Kurasa, aku adalah salah satu dari segelintir orang yang bisa sedikit memahaminya.",
  ui_story_5012_50120702_33_dialog_content = "Tapi, setelah mengingat masa-masa itu sekarang, barulah aku sadar bahwa Her Majesty memang selalu penuh keteguhan dan keyakinan.",
  ui_story_5012_50120702_34_dialog_content = "Keteguhan yang sangat kuat... Seakan-akan memang itu sudah sifat bawaannya sejak lahir.",
  ui_story_5012_50120702_35_dialog_content = "Dalam hal ini, beliau berbeda dari semua raja yang dulu pernah kunobatkan.",
  ui_story_5012_50120702_36_dialog_content = "Lihat di hadapanmu...",
  ui_story_5012_50120702_37_dialog_content = "Dengan memandang ke dalam cermin malam ini, Her Majesty mengizinkanmu mengintip sekelumit masa lalunya.",
  ui_story_5012_50120702_38_dialog_content = "Sekarang, untuk menyiapkan diri untuk naik takhta, beliau harus meninggalkan bagian dirinya dari masa lalu... Bagian dirinya yang bernama Shaya.",
  ui_story_5012_50120702_39_option_content = "Aku paham",
  ui_story_5012_50120702_40_dialog_content = "Dan, sekarang juga sudah hampir tiba waktunya.",
  ui_story_5012_50120702_41_option_content = "Aku masih belum paham...",
  ui_story_5012_50120702_42_dialog_content = "Kalau begitu, bagaimana kalau kita ke sana dan melihatnya?",
  ui_story_5012_50120702_43_dialog_content = "Ayo, kita tunggu di dekat Lake Mirror.",
  ui_story_5012_50120702_44_dialog_content = "...",
  ui_story_5012_50120702_45_dialog_content = "Lady Shaya, apa kau sudah selesai mengucapkan salam perpisahan kepada teman-teman mainanmu?",
  ui_story_5012_50120702_46_dialog_content = "Oh, kau juga di sini...",
  ui_story_5012_50120702_47_dialog_content = "Bu-Bukan begitu! Aku hanya sedang menata mereka sebelum kita pergi!",
  ui_story_5012_50120702_48_dialog_content = "Bukannya ini semua... Mainan?",
  ui_story_5012_50120702_49_dialog_content = "(\"Meninggalkan bagian dirinya yang bernama 'Shaya'...\" Mungkinkah ini yang dimaksud Novio?)",
  ui_story_5012_50120702_50_dialog_content = "Ini hanya barang tak bermakna, tak lebih! Termasuk... Yang ini.",
  ui_story_5012_50120702_51_dialog_content = "Itu jam pasir yang sangat indah, 'kan?",
  ui_story_5012_50120702_52_dialog_content = "Memang, dan itu juga merupakan barang kesayangan Lady Shaya.",
  ui_story_5012_50120702_53_dialog_content = "Tolong buang yang ini bersama yang lainnya, Novio.",
  ui_story_5012_50120702_54_dialog_content = "...",
  ui_story_5012_50120702_55_dialog_content = "... Benar, Yang Mulia. Aku yakin seluruh persiapannya sudah selesai.",
  ui_story_5012_50120702_56_dialog_content = "Aku paham.",
  ui_story_5012_50120702_57_dialog_content = "Nah, kalau begitu, Lady Shaya... Silakan lihat baik-baik ke dalam permukaan Lake Mirror...",
  ui_story_5012_50120702_58_dialog_content = "\"Demikianlah, kenangan masa lalu akan terlupakan...\"",
  ui_story_5012_50120702_59_dialog_content = "\"Agar kekuatan negeri kita yang megah dan berumur panjang ini bisa kembali terbangun...\"",
  ui_story_5012_50120702_60_dialog_content = "\"Jiwa yang paling murni, mengabdikan seluruh dirinya bagi seluruh Northland, menanti terciptanya perjanjian baru...\"",
  ui_story_5012_50120702_61_dialog_content = "<color=#e8d9bb>Wuuuuuu... Wuuuuuu...</color>",
  ui_story_5012_50120702_62_dialog_content = "Ah... Trompet Winter Palace sudah ditiup.",
  ui_story_5012_50120702_63_dialog_content = "Mari ikut dengan kami, Lord PlayerName. Upacara penobatan pemimpin baru kita akan segera dimulai.",
  ui_story_5012_50120702_64_dialog_content = "Kau sudah siap, Putri Mahkota Northland?",
  ui_story_5012_50120702_65_dialog_content = "Ya saya, Pak Novio.",
  ui_story_5012_50120801_1_dialog_content = "<color=#e8d9bb>Wuuuuuu... Wuuuuuu...</color>",
  ui_story_5012_50120801_2_dialog_content = "Orang-orang ini... Apa mereka juga sedang menuju ke Winter Palace, seperti kita?",
  ui_story_5012_50120801_3_dialog_content = "Benar. Suara yang baru saja kau dengar adalah suara trompet Winter Palace, suara yang jarang terdengar di kerajaan kami.",
  ui_story_5012_50120801_4_dialog_content = "Saat trompet itu ditiup, berarti ada peristiwa penting yang sedang terjadi di dalam Winter Palace.",
  ui_story_5012_50120801_5_dialog_content = "Sejak takhta Northland ditinggalkan, setiap orang Northland sudah menanti untuk mendengar trompet itu ditiup.",
  ui_story_5012_50120801_6_dialog_content = "Aku yakin, tak seorang pun mau melewatkan kesempatan untuk menyaksikan penobatan pemimpin baru kami.",
  ui_story_5012_50120801_7_dialog_content = "...",
  ui_story_5012_50120801_8_dialog_content = "Sekarang, gerbang-gerbang Winter Palace mestinya sudah terbuka dan kita semua bisa masuk.",
  ui_story_5012_50120801_9_dialog_content = "Benar, Yang Mulia... Anda berkeringat...",
  ui_story_5012_50120801_10_dialog_content = "Ada banyak sekali orang berkerumun memenuhi jalanan. Tolong pegang lenganku erat-erat, Lady Shaya.",
  ui_story_5012_50120801_11_dialog_content = "Novio, kau sudah mengajar banyak raja dan ratu. Apa yang biasanya mereka bicarakan sebelum upacara penobatan?",
  ui_story_5012_50120801_12_dialog_content = "Merasa gugup itu wajar. Anda bebas bicara apa saja, Yang Mulia.",
  ui_story_5012_50120801_13_dialog_content = "Apa kau ingat saat aku masih berusia sekitar lima tahun, kau sering mengajariku tentang sejarah Northland?",
  ui_story_5012_50120801_14_dialog_content = "Tentu, Yang Mulia. Anda pernah lari kebingungan dan bersembunyi di dalam hutan. Hari itu, berjam-jam aku mencari Anda di tengah hamparan salju dan pepohonan.",
  ui_story_5012_50120801_15_dialog_content = "Lalu, setelah aku mempelajari ilmu pedang... aku bahkan bisa membelah kristal Northland Pine dengan mudah!",
  ui_story_5012_50120801_16_dialog_content = "Benar, Lady Shaya. Kau bahkan menyimpan salah satu serpihan kristal itu dan memberikannya kepadaku sebagai hadiah ulang tahunku.",
  ui_story_5012_50120801_17_dialog_content = "Lalu, untuk membalas pemberianku itu... Kau memberiku sebuah mainan.",
  ui_story_5012_50120801_18_dialog_content = "Ah... Tak usah dibicarakan lagi, Lady Shaya. Jam pasir itu bukan barang berharga, hanya hadiah kecil, tak lebih.",
  ui_story_5012_50120801_19_dialog_content = "Saat itu, jam pasir seperti itu cukup digemari anak-anak Wonder Village. Aku hanya merasa bahwa kau pasti juga akan menyukainya.",
  ui_story_5012_50120801_20_dialog_content = "Anak-anak Northland sering kali bisa menemukan cara unik untuk bersenang-senang...",
  ui_story_5012_50120801_21_dialog_content = "Bermain teka-teki di tepi Lake Mirror, atau lari balapan naik turun Pine Frost Valley... Mereka sungguh tahu caranya bersenang-senang, ya?",
  ui_story_5012_50120801_22_dialog_content = "Jangan lupa, Nona... Kau juga anak kecil.",
  ui_story_5012_50120801_23_dialog_content = "...",
  ui_story_5012_50120801_24_dialog_content = "Tunggu...",
  ui_story_5012_50120801_25_dialog_content = "<size=45><color=#e8d9bb>Duarr...</color></size>",
  ui_story_5012_50120801_26_dialog_content = "...Suara kencang barusan itu apa?!",
  ui_story_5012_50120801_27_dialog_content = "Graaaaaagh!!!",
  ui_story_5012_50120801_28_dialog_content = "Gahhhh!",
  ui_story_5012_50120801_28X1_dialog_content = "Bahkan ibu kota sudah...!",
  ui_story_5012_50120801_28X2_dialog_content = "Kalau situasinya terus begini...",
  ui_story_5012_50120801_29_dialog_content = "Seorang \"anak kecil\"... Tak mungkin bisa melindungi seluruh Northland.",
  ui_story_5012_50120801_30_dialog_content = "Satu-satunya orang yang bisa membawa kembali kedamaian dan perlindungan ke Northland... adalah <color=#FFB400>Bethlehem</color>\".",
  ui_story_5012_50120901_1_dialog_content = "Para Eclipsite itu... Mereka membuntuti kita ke Winter Palace...",
  ui_story_5012_50120901_2_dialog_content = "Parah... Akan butuh waktu lama untuk membasmi mereka semua...",
  ui_story_5012_50120901_3_dialog_content = "Master Novio, tolong bantu evakuasi warga yang ada di dekat sini.",
  ui_story_5012_50120901_4_dialog_content = "Akan kulumat para Eclipsite itu dengan tanganku sendiri.",
  ui_story_5012_50120901_5_dialog_content = "Trompetnya masih berbunyi, Nona. Kau tak boleh berhenti atas alasan apa pun.",
  ui_story_5012_50120901_6_dialog_content = "Sepanjang sejarah kita, belum pernah ada raja yang menyela upacara penobatan.",
  ui_story_5012_50120901_7_dialog_content = "Tapi, mana mungkin kita tutup mata sementara rakyat kita dirundung bahaya dan kehancuran?",
  ui_story_5012_50120901_8_dialog_content = "Semua upacara ini tak ada artinya kalau negeri dan rakyat kita harus menderita karenanya!",
  ui_story_5012_50120901_9_dialog_content = "...Baiklah, Nona...",
  ui_story_5012_50120901_10_dialog_content = "<size=45>Graaauuugh!!!</size>",
  ui_story_5012_50120901_11_dialog_content = "Pisau Aurora!!!",
  ui_story_5012_50120901_12_dialog_content = "Queen Beth... Maksudku, Lady Shaya! Di belakang Anda!",
  ui_story_5012_50120901_13_dialog_content = "Ngh... Sungguh menjengkelkan.",
  ui_story_5012_50120901_14_dialog_content = "Extreme Cold...",
  ui_story_5012_50120901_15_dialog_content = "Graaagh...",
  ui_story_5012_50120901_16_dialog_content = "Untuk sementara ini, gerbang-gerbang Winter Palace sudah ditutup, Lady Shaya. Semua orang di sekitar sini yang selamat sudah diamankan di dalam istana.",
  ui_story_5012_50120901_17_dialog_content = "Tapi... Kalau para Eclipsite itu terus mengepung Winter Palace, cepat atau lambat mereka pasti akan berhasil menerobos masuk.",
  ui_story_5012_50120901_18_dialog_content = "Satu-satunya harapan kita adalah kau harus segera mendapatkan kekuatan <color=#FFB400>Spark</color>, dan mengaktifkan kembali <color=#FFB400>Sanctuary</color> untuk menyingkirkan makhluk-makhluk jahat itu dari Northland.",
  ui_story_5012_50120901_19_dialog_content = "Dengan begitu, dan hanya dengan cara itulah negeri kita bisa kembali damai dan aman.",
  ui_story_5012_50120901_20_dialog_content = "...",
  ui_story_5012_50120901_21_dialog_content = "Aku paham.",
  ui_story_5012_50120901_22_dialog_content = "Ayo, Master Novio... Kau juga, Caelestite. Ayo kita masuk.",
  ui_story_5012_50120901_23_dialog_content = "Lady Shaya... Sang calon Ratu...",
  ui_story_5012_50120901_24_dialog_content = "Nona... Takhta sudah lama menanti kedatanganmu.",
  ui_story_5012_50120901_25_dialog_content = "Mulai hari ini dan seterusnya, kami akan sepenuhnya mengabdi dan setia kepadamu.",
  ui_story_5012_50120901_26_dialog_content = "Rakyat Northland yang baik, kalian tak harus kaku dalam memegang keyakinan. Dunia ini terus berubah setiap hari, dan tradisi kita pun harus ikut berubah...",
  ui_story_5012_50120901_27_dialog_content = "Tapi, kita harus selalu ingat untuk memuja Northland, tanah kelahiran kita.",
  ui_story_5012_50120901_28_dialog_content = "Karena Northland-lah yang memberi kita kehidupan dan menopang kita hingga napas penghabisan kita. Negeri ini adalah ibu kita, dan kita adalah anak-anaknya.",
  ui_story_5012_50120901_29_dialog_content = "Demi Utara! Hidup kita demi Northland!",
  ui_story_5012_50120901_30_dialog_content = "Demi Utara! Hidup kita demi Northland!",
  ui_story_5012_50120901_31_dialog_content = "Upacara penobatan sudah dimulai kembali, Nona.",
  ui_story_5012_50120901_32_dialog_content = "Sekarang, kau tak bisa mundur lagi. Naikilah anak tangga menuju takhta, dan ambillah kekuatan Spark.",
  ui_story_5012_50120901_33_dialog_content = "...",
  ui_story_5012_50120901_34_dialog_content = "Master Novio...",
  ui_story_5012_50120901_35_dialog_content = "Majulah.",
  ui_story_5012_50120901_36_dialog_content = "Baik...!",
  ui_story_5012_50120901_37_dialog_content = "<color=#e8d9bb>Bruak...!</color>",
  ui_story_5012_50120901_38_dialog_content = "Para monster itu! Mereka... Mereka berhasil menerobos masuk!",
  ui_story_5012_50120901_39_dialog_content = "M-Master Novio?!",
  ui_story_5012_50120901_40_dialog_content = "Waktu sedang tidak berpihak kepada kita! Ingat, Nona: sekarang, kau tak bisa mundur lagi!",
  ui_story_5012_50120901_41_dialog_content = "Soal para pengganggu itu...",
  ui_story_5012_50120901_42_dialog_content = "Biar kami tangani mereka!",
  ui_story_5012_50120902_1_dialog_content = "Ki-Kita selamat...",
  ui_story_5012_50120902_2_dialog_content = "Sepertinya kita berhasil membasmi semua Eclipsite di sekitar sini...",
  ui_story_5012_50120902_3_dialog_content = "Aku ingin tahu keadaan Shaya...",
  ui_story_5012_50120902_4_dialog_content = "Lihat saja sendiri, Lord PlayerName.",
  ui_story_5012_50120902_5_dialog_content = "Spark sudah kembali menyala...",
  ui_story_5012_50120902_6_dialog_content = "Mari hening sejenak untuk menghormati peristiwa bersejarah ini.",
  ui_story_5012_50120902_7_dialog_content = "<color=#e8d9bb>Di Winter Palace, di sebelah takhta...</color>",
  ui_story_5012_50120902_8_dialog_content = "Salju yang mencair mengalirkan air melewati pegunungan dan sungai, membawa kehidupan bagi negeri penuh berkah ini.",
  ui_story_5012_50120902_9_dialog_content = "Seiring suara deru guntur yang memecah kesunyian yang melingkupi negeri ini, sepercik nyala api bergelora, membakar semua yang sudah layu dan mati.",
  ui_story_5012_50120902_10_dialog_content = "Cahaya abadi dan mulia ini bersinar atas Anda hari ini. Yang Mulia, angkatlah kepala Anda untuk menyambutnya.",
  ui_story_5012_50120902_11_dialog_content = "Seperti halnya keluarga kerajaan memilih Spark, demikian pulalah Spark memilih penerus yang akan mewarisinya.",
  ui_story_5012_50120902_12_dialog_content = "Sebelum mewarisi kekuatan Spark, ada satu hal terakhir yang harus kaulakukan, dan harus kaulakukan sendiri.",
  ui_story_5012_50120902_13_dialog_content = "Yang Mulia... Silakan daraskan sumpah kerajaan sebagai wujud persembahan bagi Spark.",
  ui_story_5012_50120902_14_dialog_content = "...",
  ui_story_5012_50120902_15_dialog_content = "Sejak dulu, pedang dan tongkat kerajaan ini menjadi lambang kekuatan mutlak di negeri ini.",
  ui_story_5012_50120902_16_dialog_content = "Dengan menggunakan salah satu dari kedua benda ini, kita bisa menaklukkan negara lain.",
  ui_story_5012_50120902_17_dialog_content = "Tapi, di kerajaan-kerajaan yang tak terselimuti salju putih bersih...",
  ui_story_5012_50120902_18_dialog_content = "Sudah cukup banyak terjadi pemberontakan dan pertentangan.",
  ui_story_5012_50120902_19_dialog_content = "Aku bersumpah akan menerima kekuatan Spark, dan akan memimpin Northland menuju masa panjang penuh kedamaian, ketenangan, dan kemakmuran.",
  ui_story_5012_50120902_20_dialog_content = "\"Demi Utara, demi sesama, dan negara.\"",
  ui_story_5012_50120902_21_dialog_content = "Atas nama Bethlehem, saat ini saya bersumpah untuk menggunakan kekuatan Spark untuk melindungi seluruh Northland!",
  ui_story_5012_50120902_22_dialog_content = "Atas nama para raja dan ratu terdahulu, rakyat Northland, dan daratan salju yang luas dan tak berbatas...",
  ui_story_5012_50120902_23_dialog_content = "Kunobatkan engkau menjadi Ratu Northland dan Pelindung Spark... Her Majesty Bethlehem!",
  ui_story_5012_50120902_24_dialog_content = "<size=45>Hidup sang Ratu!</size>",
  ui_story_5012_50120902_25_dialog_content = "<color=#e8d9bb>Demikianlah, sang ratu muda itu mengangkat kepalanya, seakan mendengarkan bisikan dari kekuatan kuno yang mulia...</color>",
  ui_story_5012_50120902_26_dialog_content = "Spark akhirnya memilihmu. Kau sudah melakukannya dengan baik...",
  ui_story_5012_50120902_27_dialog_content = "Queen Bethlehem.",
  ui_story_5012_50120902_28_dialog_content = "Terima kasih, Master Novio.",
  ui_story_5012_50121001_1_dialog_content = "Northland sudah lama menanti kehadiran ratunya, Yang Mulia.",
  ui_story_5012_50121001_2_dialog_content = "...",
  ui_story_5012_50121001_3_dialog_content = "Ba-Bagaimana bisa...",
  ui_story_5012_50121001_4_dialog_content = "Ba-Bagaimana bisa dia berubah begitu banyak dalam sekejap?!",
  ui_story_5012_50121001_5_dialog_content = "Apakah benar-benar seperti ini yang dulu terjadi?",
  ui_story_5012_50121001_6_dialog_content = "Atau ini hanya penglihatan...?",
  ui_story_5012_50121001_7_dialog_content = "Jangan pernah lupakan saat ini: saat kekuatan untuk mempertahankan Northland terbangun dari dalam garis keturunan keluarga kerajaan kuno yang mengalir dalam darahmu.",
  ui_story_5012_50121001_8_dialog_content = "Spark, yang bersemayam di atas takhta kerajaan kita, sudah menyala sejak peradaban kita bermula.",
  ui_story_5012_50121001_9_dialog_content = "Sampaikan terima kasih kepadanya dan kepada para pendahulumu, karena berkat perlindungan merekalah, negeri kita yang beku ini bisa menghidupi rakyatnya.",
  ui_story_5012_50121001_10_dialog_content = [[
Hari ini, awan gelap di atas sana mulai pudar,
karena Ratu Northland kembali menduduki takhtanya.]],
  ui_story_5012_50121001_11_dialog_content = "Lalu, apa yang diinginkan Northland dariku sekarang?",
  ui_story_5012_50121001_12_dialog_content = "Dengan rendah hati kami memintamu pergi ke <color=#FFB400>Beacon</color> yang ada di tepi laut, dan menyalakannya kembali.",
  ui_story_5012_50121001_13_dialog_content = "Dalam masa-masa kegelapan, rakyat berdoa agar cahayanya kembali menyala, dan mereka bisa terselamatkan dari yang jahat.",
  ui_story_5012_50121001_14_dialog_content = "Baiklah.",
  ui_story_5012_50121001_15_dialog_content = "Aku paham.",
  ui_story_5012_50121001_16_dialog_content = "Tunggu!",
  ui_story_5012_50121001_17_dialog_content = "Izinkan aku ikut dengan Anda! Lagi pula, selama ini kita sudah bertarung bersama!",
  ui_story_5012_50121001_18_dialog_content = "Walaupun sekarang Anda sudah jauh lebih kuat, aku...",
  ui_story_5012_50121001_19_dialog_content = "Aku tahu aku masih bisa membantu dalam hal-hal tertentu!",
  ui_story_5012_50121001_20_dialog_content = "...",
  ui_story_5012_50121001_21_dialog_content = "Eh?",
  ui_story_5012_50121001_22_dialog_content = "Ke-Kenapa dia tidak mengacuhkanku?",
  ui_story_5012_50121001_23_dialog_content = "Tunggu! Shaya!",
  ui_story_5012_50121001_24_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5012_50121001_25_dialog_content = "Cukup.",
  ui_story_5012_50121001_26_dialog_content = "Dia sudah menanggalkan nama itu. Sekarang, nama itu tak akan dikenal lagi.",
  ui_story_5012_50121001_27_dialog_content = "Satu-satunya orang yang ada adalah Queen Bethlehem.",
  ui_story_5012_50121001_28_dialog_content = "Tapi, kenapa?",
  ui_story_5012_50121001_29_dialog_content = "Sekarang dia hanya menggunakan nama lain, 'kan? Dia masih orang yang sama seperti dulu!",
  ui_story_5012_50121001_30_dialog_content = "Ya, tapi sekarang... Dia adalah ratu seluruh Northland.",
  ui_story_5012_50121001_31_dialog_content = "Dan, karenanya, sekarang dia pergi untuk terjun dalam pertarungan yang hanya bisa dilakukan olehnya saja.",
  ui_story_5012_50121001_32_dialog_content = "\"Pertarungan yang hanya bisa dilakukan olehnya saja\"? Apa maksudnya?",
  ui_story_5012_50121001_33_dialog_content = "Itu tanggung jawab dan beban yang harus ditanggungnya sebagai pewaris Spark.",
  ui_story_5012_50121001_34_dialog_content = "Orang-orang yang tak punya kekuatan tak diizinkan dan tak pantas ikut dengannya.",
  ui_story_5012_50121001_35_dialog_content = "Karena dia telah meninggalkan rasa cinta dirinya, dan kini dia bertarung bukan demi dirinya sendiri, melainkan demi seluruh Northland.",
  ui_story_5012_50121001_36_dialog_content = "Itu... Tetap terdengar tak masuk akal bagiku.",
  ui_story_5012_50121001_37_dialog_content = "Wajar saja.",
  ui_story_5012_50121001_38_dialog_content = "Ketahuilah, semuanya berjalan sesuai rencana.",
  ui_story_5012_50121001_39_dialog_content = "Sang Ratu mengemban tanggung jawab untuk membebaskan Northland dari hal-hal jahat, dan menyelamatkan kerajaan ini dari segala macam ancaman.",
  ui_story_5012_50121001_40_dialog_content = "Tanggung jawab sang Ratu...",
  ui_story_5012_50121001_41_dialog_content = "Benar.",
  ui_story_5012_50121001_42_dialog_content = "...",
  ui_story_5012_50121001_43_dialog_content = "Tidak! Aku tak bisa menerimanya!",
  ui_story_5012_50121001_44_dialog_content = "Hmm?",
  ui_story_5012_50121001_45_dialog_content = "Ini seperti memberikan buku cerita untuk kubaca!",
  ui_story_5012_50121001_46_dialog_content = "Kau memberikannya kepadaku dan memintaku membacanya, dan aku sudah membacanya...",
  ui_story_5012_50121001_47_dialog_content = "Bagaimana mungkin kau menyuruhku berhenti membaca sebelum tahu akhir ceritanya?!",
  ui_story_5012_50121001_48_dialog_content = "Tunggu! Kau tak boleh pergi!",
  ui_story_5012_50121001_49_dialog_content = "Shaya? Di mana...?",
  ui_story_5012_50121001_50_dialog_content = "Graaagh!",
  ui_story_5012_50121001_51_dialog_content = "Graah! Graaah!!",
  ui_story_5012_50121001_52_dialog_content = "E-Eclipsite?!",
  ui_story_5012_50121001_53_dialog_content = "Seperti yang sudah kukatakan tadi... Ini pertarungan.",
  ui_story_5012_50121002_1_dialog_content = "Aku tak tahu pertarungannya separah itu...",
  ui_story_5012_50121002_2_dialog_content = "Nah, sekarang kau sudah tahu.",
  ui_story_5012_50121002_3_dialog_content = "Bagi orang biasa, terjun ke dalam pertarungan itu sama saja artinya dengan bunuh diri.",
  ui_story_5012_50121002_4_dialog_content = "Tapi, kita sudah tertinggal jauh di belakang sang Ratu. Tak mungkin kita bisa menyusulnya.",
  ui_story_5012_50121002_5_dialog_content = "...",
  ui_story_5012_50121002_6_dialog_content = "Aku masih belum paham, Novio.",
  ui_story_5012_50121002_7_dialog_content = "Siapa yang sesungguhnya menjadi ratu sekarang?",
  ui_story_5012_50121002_8_dialog_content = "Apakah Shaya, yang baru saja duduk di takhta... Atau Queen Bethlehem, yang tadi menyambut kami saat tiba di Northland?",
  ui_story_5012_50121002_9_dialog_content = "Maksud pertanyaanmu adalah apakah ratu kami adalah orang yang tampak dalam ingatan ini, atau sang ratu dalam dunia nyata?",
  ui_story_5012_50121002_10_dialog_content = "Y-ya...",
  ui_story_5012_50121002_11_dialog_content = "Maksudku, setelah dia mewarisi Spark, dia seakan-akan langsung berubah menjadi orang yang sama sekali berbeda...",
  ui_story_5012_50121002_12_dialog_content = "Karena kita sedang melihat ingatan masa lalu, dalam ruang ini, dia baru saja naik takhta.",
  ui_story_5012_50121002_13_dialog_content = "Tapi, memang tak bisa dipungkiri bahwa kesadaran sang Ratu sudah terbangun dalam garis darahnya.",
  ui_story_5012_50121002_14_dialog_content = "Jadi... Aku harus memanggilnya dengan nama apa?",
  ui_story_5012_50121002_15_dialog_content = "Dalam penglihatan ini, Shaya seperti gadis kecil... Tapi di dunia nyata, Ratu Bethlehem berbicara dan bertindak sangat berbeda. Aku merasa aku harus memanggilnya seperti kakakku...",
  ui_story_5012_50121002_16_dialog_content = "Kurasa kau tak perlu terlalu memikirkan hal ini.",
  ui_story_5012_50121002_17_dialog_content = "Terlepas dari ruang atau waktu, asalkan dia sudah menuntaskan ritual naik takhta, dia adalah Queen Bethlehem.",
  ui_story_5012_50121002_18_dialog_content = "Walau waktu berlalu, jati dirinya tidaklah berubah. Queen Bethlehem yang dulu tidaklah berbeda dari Queen Bethlehem yang sekarang.",
  ui_story_5012_50121002_19_dialog_content = "A-aku paham...",
  ui_story_5012_50121002_20_dialog_content = "Benar.",
  ui_story_5012_50121002_21_dialog_content = "Sang Ratu tak akan pernah berubah, sama seperti Northland sendiri.",
  ui_story_5012_50121002_22_dialog_content = "Bahkan, walaupun kesadaran sang Ratu sudah terbangun, kewajibannya terhadap kerajaan kami tetaplah sama.",
  ui_story_5012_50121002_23_dialog_content = "Maksudmu tugas untuk menyalakan kembali obor di Lighthouse, 'kan?",
  ui_story_5012_50121002_24_dialog_content = "Apa ada makna tertentu dari ritual ini?",
  ui_story_5012_50121002_25_dialog_content = "Akan kucoba menjelaskannya semampuku.",
  ui_story_5012_50121002_26_dialog_content = "Baiklah, aku siap menyimak!",
  ui_story_5012_50121002_27_dialog_content = "Dari masa ke masa, Northland diberkati dengan karunia besar dan hebat.",
  ui_story_5012_50121002_28_dialog_content = "Kau dan seluruh dunia mengenal berkat ini dengan nama \"Luminatics\".",
  ui_story_5012_50121002_29_dialog_content = "Luminatics ini melingkupi seluruh kerajaan kami, dari ujung ke ujung, melindungi kerajaan dari segala bentuk serangan Eclipsite.",
  ui_story_5012_50121002_30_dialog_content = "Kami menyebut kekuatan ini dengan nama \"<color=#FFB400>Sanctuary</color>\".",
  ui_story_5012_50121002_31_dialog_content = "Oh, begitu.",
  ui_story_5012_50121002_32_dialog_content = "Jelas, butuh kekuatan luar biasa besar untuk menjaga Luminatics seperti ini.",
  ui_story_5012_50121002_33_dialog_content = "Nah, soal sumber kekuatannya... Aku yakin kau sudah bisa menebaknya.",
  ui_story_5012_50121002_34_dialog_content = "Kekuatan Spark...",
  ui_story_5012_50121002_35_dialog_content = "Benar.",
  ui_story_5012_50121002_36_dialog_content = "Itu juga menjadi alasan kenapa Northland harus selalu punya raja atau ratu.",
  ui_story_5012_50121002_37_dialog_content = "Beacon itu adalah inti \"Sanctuary\".",
  ui_story_5012_50121002_38_dialog_content = "Selama obornya tetap menyala, daerah di dalam batas kerajaan kami akan tetap aman dari mara bahaya.",
  ui_story_5012_50121002_39_dialog_content = "Tapi, seperti yang kau lihat sekarang, di arah Beacon sana tampak gelap gulita.",
  ui_story_5012_50121002_40_dialog_content = "Dengan kekuatan yang baru saja diwarisinya, sang Ratu harus pergi ke Beacon dan menyalakan kembali Sanctuary.",
  ui_story_5012_50121002_41_dialog_content = "Saat obornya sudah dinyalakan kembali, barulah kita akan bebas dari krisis ini dan bisa kembali hidup damai.",
  ui_story_5012_50121002_42_dialog_content = "Tapi, itu tanggung jawab yang sangat besar... Apa dia akan baik-baik saja melakukannya sendirian?",
  ui_story_5012_50121002_43_dialog_content = "Ada banyak sekali musuh di antara dia dan Beacon... Belum lagi, kondisi alam Northland yang keras ini...",
  ui_story_5012_50121002_44_dialog_content = "Dan, sebelum dia pergi tadi, dia jelas...",
  ui_story_5012_50121002_45_dialog_content = "Tak ada cara lain.",
  ui_story_5012_50121002_46_dialog_content = "Sebagai Ratu Northland dan pewaris Spark, ini memang kewajibannya seorang.",
  ui_story_5012_50121002_47_dialog_content = "Tak seorang pun bisa membantunya sekarang.",
  ui_story_5012_50121002_48_dialog_content = "...Seperti itukah keyakinanmu dan seluruh rakyat Northland?",
  ui_story_5012_50121002_49_dialog_content = "Aku masih belum bisa menerimanya sama sekali, tapi... aku akan berusaha semampuku untuk memahaminya.",
  ui_story_5012_50121101_1_dialog_content = "Dia makin dekat!",
  ui_story_5012_50121101_2_dialog_content = "Aku bisa melihatnya di sana...",
  ui_story_5012_50121101_3_dialog_content = "Luar biasa...",
  ui_story_5012_50121101_4_dialog_content = "<size=45>Graaah!</size>",
  ui_story_5012_50121101_5_dialog_content = "Awas!",
  ui_story_5012_50121101_6_dialog_content = "Tetap waspada; kau justru lebih terancam bahaya di sini daripada dia di sana!",
  ui_story_5012_50121101_7_dialog_content = "Ma-Maafkan aku...",
  ui_story_5012_50121101_8_dialog_content = "Kau benar, aku harus fokus pada sekitarku.",
  ui_story_5012_50121101_9_dialog_content = "Sang Ratu di depan sana! Kalau berusaha, kita pasti bisa menyusulnya!",
  ui_story_5012_50121101_10_dialog_content = "...",
  ui_story_5012_50121101_11_dialog_content = "Aku tak bisa beralih dari posisiku.",
  ui_story_5012_50121101_12_dialog_content = "Kita tak boleh mendekat lagi.",
  ui_story_5012_50121101_13_dialog_content = "Tapi, kenapa?",
  ui_story_5012_50121101_14_dialog_content = "Jalan yang harus ditempuhnya sampai ke Beacon masih panjang... Memangnya kau bisa tenang saja melihatnya bertarung seorang diri?",
  ui_story_5012_50121101_15_dialog_content = "Ya.",
  ui_story_5012_50121101_16_dialog_content = "Ka-Kau...",
  ui_story_5012_50121101_17_dialog_content = "Kukira kau menyayangi sang Ratu...",
  ui_story_5012_50121101_18_dialog_content = "Tapi, sepertinya kau tak lebih dari sekadar bawahannya yang setia, iya 'kan?",
  ui_story_5012_50121101_19_dialog_content = "... Benar.",
  ui_story_5012_50121101_20_dialog_content = "Omong kosong! Aku tahu perasaanmu sesungguhnya sama sekali bukan seperti itu!",
  ui_story_5012_50121101_21_dialog_content = "Ingat, aku ini Caelestite! Aku bisa tahu dengan pasti isi hati orang lain!",
  ui_story_5012_50121101_22_dialog_content = "Jangan kira kau bisa membodohiku!",
  ui_story_5012_50121101_23_dialog_content = "Pikiran dan perasaanku sudah tak penting lagi.",
  ui_story_5012_50121101_24_dialog_content = "Ini tradisi kami, yang sudah ribuan tahun melindungi Northland.",
  ui_story_5012_50121101_25_dialog_content = "Tradisi yang mana yang kaumaksud?",
  ui_story_5012_50121101_26_dialog_content = "Tadi kau sudah melihatnya sendiri: agar bisa naik takhta, calon penerus harus meninggalkan rasa cinta dirinya.",
  ui_story_5012_50121101_27_dialog_content = "Ya, aku memang sudah melihatnya sendiri...",
  ui_story_5012_50121101_28_dialog_content = "Dia mengorbankan hal-hal yang paling dikasihinya, dan bahkan namanya sendiri.",
  ui_story_5012_50121101_29_dialog_content = "Tapi, itu masih belum cukup.",
  ui_story_5012_50121101_30_dialog_content = "Dia juga harus meninggalkan orang-orang yang dulu disebutnya \"teman\".",
  ui_story_5012_50121101_31_dialog_content = "Bahkan teman-temannya...?",
  ui_story_5012_50121101_32_dialog_content = "Tapi, aku ingat kaubilang dulu dia tak punya teman sebaya, hanya...",
  ui_story_5012_50121101_33_dialog_content = "Yang kaulihat sekarang ini hanyalah penglihatan masa lalu, tak lebih.",
  ui_story_5012_50121101_34_dialog_content = "Pada kenyataannya, akulah yang menemaninya hingga akhir jalan ini.",
  ui_story_5012_50121101_35_dialog_content = "Dari Lake Mirror, kami berjalan kaki ke Winter Palace... Dan dia menggondeli bajuku sepanjang jalan, sama seperti saat dia masih kecil.",
  ui_story_5012_50121101_36_dialog_content = "Dia bicara lebih banyak dibandingkan biasanya, karena dia gugup jika harus mengatakan semua yang menurutnya harus disampaikan sebelum akhir.",
  ui_story_5012_50121101_37_dialog_content = "Saat sudah sampai di Winter Palace, dia melonggarkan pegangannya pada bajuku.",
  ui_story_5012_50121101_38_dialog_content = "Aku harus berlutut untuk memasangkan mahkota kerajaan kami ke kepalanya.",
  ui_story_5012_50121101_39_dialog_content = "Tubuhnya belum cukup tinggi... Dia adalah ratu termuda yang pernah kulayani semasa hidupku.",
  ui_story_5012_50121101_40_dialog_content = "Aku melihat dia berkedip sebelum sebagian sinar di matanya pudar dan digantikan oleh wibawa yang begitu tenang dan kukuh seperti air di Lake Mirror.",
  ui_story_5012_50121101_41_dialog_content = "Dia mendongak ke arahku, menungguku untuk menobatkannya menjadi Queen Bethlehem, penguasa Northland.",
  ui_story_5012_50121101_42_dialog_content = "Sejak saat itu, hubungan persahabatan di antara kami terputus untuk selamanya...",
  ui_story_5012_50121101_43_dialog_content = "Yang ada hanyalah ikatan antara penguasa dan hambanya.",
  ui_story_5012_50121101_44_dialog_content = "Tapi, bagaimana... Bagaimana mungkin kau bisa melakukannya...?",
  ui_story_5012_50121101_45_dialog_content = "Selama ini kau membesarkannya seperti putrimu sendiri, lalu kau melepaskannya begitu saja...",
  ui_story_5012_50121101_46_dialog_content = "Aku tak akan bisa melakukannya... Aku tak akan bisa melakukannya, entah sekarang, entah kapan pun...",
  ui_story_5012_50121101_47_dialog_content = "Itu memang wajar.",
  ui_story_5012_50121101_48_dialog_content = "Untungnya, umurku jauh lebih panjang dibandingkan manusia pada umumnya.",
  ui_story_5012_50121101_49_dialog_content = "Seumur hidupku, aku sudah membesarkan banyak raja dan ratu, dan aku punya banyak kesempatan untuk membiasakan diri dengan perpisahan semacam itu.",
  ui_story_5012_50121101_50_dialog_content = "Apakah selalu seperti itu... Yang terjadi pada setiap raja dan ratu yang kaubesarkan?",
  ui_story_5012_50121101_51_dialog_content = "Ya.",
  ui_story_5012_50121101_52_dialog_content = "Percayalah padaku, aku juga tak suka kalau harus begini... Tapi, aku sudah terbiasa.",
  ui_story_5012_50121101_53_dialog_content = "Demi Northland... Begitu, 'kan?",
  ui_story_5012_50121101_54_dialog_content = "Tentu saja.",
  ui_story_5012_50121101_55_dialog_content = "Kalau takhta Northland kosong, negeri kami tak akan bisa hidup damai maupun makmur.",
  ui_story_5012_50121101_56_dialog_content = "...",
  ui_story_5012_50121101_57_dialog_content = "Kau... Masih belum bisa menerimanya, ya?",
  ui_story_5012_50121101_58_dialog_content = "Kalau melihatnya dari sudut pandang rakyat Northland, aku bisa memahaminya...",
  ui_story_5012_50121101_59_dialog_content = "Ini memang harga mahal yang harus dibayar demi memperoleh kekuatan besar untuk melindungi seluruh kerajaan... Ini memang pilihan sulit, tapi jelas.",
  ui_story_5012_50121101_60_dialog_content = "Hanya saja... Ini terasa tragis.",
  ui_story_5012_50121101_61_dialog_content = "Penggambaran dongeng-dongeng tentang Northland sangatlah tragis.",
  ui_story_5012_50121101_62_dialog_content = "Aku minta maaf, orang asing, kalau kisah-kisah negeri kami tak sesuai dengan seleramu.",
  ui_story_5012_50121101_63_dialog_content = "Bukan begitu! Hanya saja...",
  ui_story_5012_50121101_64_dialog_content = "Aku merasa seakan-akan ada sesuatu yang hilang...",
  ui_story_5012_50121101_65_dialog_content = "Ada sesuatu... yang hilang?",
  ui_story_5012_50121101_66_dialog_content = "Benar! Bagaimana kalau begini?",
  ui_story_5012_50121101_67_dialog_content = "Semua ini hanya penglihatan masa lalu, 'kan?",
  ui_story_5012_50121101_68_dialog_content = "Benar.",
  ui_story_5012_50121101_69_dialog_content = "Kalau begitu, apa gunanya terus mempertahankan tradisi di sini?",
  ui_story_5012_50121101_70_dialog_content = "Karena di dunia nyata, kalian harus mengikuti perkembangan zaman dan mematuhi tradisi kerajaan...",
  ui_story_5012_50121101_71_dialog_content = "Kenapa kau tak coba mengungkapkan perasaanmu yang sesungguhnya di sini?",
  ui_story_5012_50121101_72_dialog_content = "...Usulmu itu sungguh menyesatkan. Tolong jangan berargumen seperti itu...",
  ui_story_5012_50121101_73_dialog_content = "Ya sudah, baiklah! Aku tak akan bicara sepatah kata pun lagi!",
  ui_story_5012_50121101_74_dialog_content = "Lagi pula, perasaanmu yang sesungguhnya sama dengan yang kurasakan!",
  ui_story_5012_50121101_75_dialog_content = "<size=45>Ayo! Kita dampingi sang Ratu dalam pertarungannya!</size>",
  ui_story_5012_50121201_1_dialog_content = "<size=45>Yang Mulia!</size>",
  ui_story_5012_50121201_2_dialog_content = "*Hosh, hosh...*",
  ui_story_5012_50121201_3_dialog_content = "Akhirnya kita... Bisa menyusulnya...",
  ui_story_5012_50121201_4_dialog_content = "...",
  ui_story_5012_50121201_5_dialog_content = "Novio pasti sudah menjelaskan semuanya kepadamu, 'kan?",
  ui_story_5012_50121201_6_dialog_content = "Ini pertarunganku, pertarunganku seorang diri.",
  ui_story_5012_50121201_7_dialog_content = "Tindakan dan niatmu sama sekali tak ada gunanya.",
  ui_story_5012_50121201_8_dialog_content = "Kenapa kau berpikir begitu?",
  ui_story_5012_50121201_9_dialog_content = "Yang kita lawan ini kan Eclipsite! Aku punya banyak alasan untuk melakukannya!",
  ui_story_5012_50121201_10_dialog_content = "Misalnya?",
  ui_story_5012_50121201_11_dialog_content = "Misalnya... Yah, semua orang pasti punya alasan untuk bertarung melawan Eclipsite, 'kan?",
  ui_story_5012_50121201_12_dialog_content = "Alasanku adalah karena dulu mereka menghancurkan negeriku dan membantai kaumku...",
  ui_story_5012_50121201_13_dialog_content = "Jadi, alasanmu bertarung adalah untuk balas dendam?",
  ui_story_5012_50121201_14_dialog_content = "Y-ya...",
  ui_story_5012_50121201_15_dialog_content = "Kurasa selama ini aku tak terlalu memikirkannya dalam-dalam sebagaimana mestinya...",
  ui_story_5012_50121201_16_dialog_content = "Kurasa, alasanku bukan balas dendam semata...",
  ui_story_5012_50121201_17_dialog_content = "Tetap saja, itu adalah alasan yang kaupilih.",
  ui_story_5012_50121201_18_dialog_content = "Kalaupun kau bisa kembali tepat saat Eraveil dihancurkan, tak mungkin kau bisa menghentikannya.",
  ui_story_5012_50121201_19_dialog_content = "Itu pasti sudah jelas bagimu, 'kan?",
  ui_story_5012_50121201_20_dialog_content = "...",
  ui_story_5012_50121201_21_dialog_content = "Balas dendam bukanlah alasan yang tepat untuk bertarung; justru hanya akan menjadi api yang menelanmu hingga habis tak bersisa.",
  ui_story_5012_50121201_22_dialog_content = "Kalau kau memang ingin terjun ke dalam pertarungan, seharusnya itu karena kau ingin melindungi sesuatu.",
  ui_story_5012_50121201_23_dialog_content = "Melindungi sesuatu...?",
  ui_story_5012_50121201_24_dialog_content = "Yang Mulia... Bagaimana Anda bisa memutuskan bahwa Anda ingin melindungi seluruh Northland?",
  ui_story_5012_50121201_25_dialog_content = "Aku lahir dan tumbuh besar di Northland.",
  ui_story_5012_50121201_26_dialog_content = "Itu saja sudah cukup menjadi alasan.",
  ui_story_5012_50121201_27_dialog_content = "Tapi... Apakah memang sepadan kalau Anda harus mengorbankan segala hal yang Anda sayangi?",
  ui_story_5012_50121201_28_dialog_content = "Melindungi adalah tanggung jawab besar.",
  ui_story_5012_50121201_29_dialog_content = "Kalau aku tak meninggalkan diriku yang lama, aku tak akan pernah pantas untuk mengemban tanggung jawab itu.",
  ui_story_5012_50121201_30_dialog_content = "Tapi, kenapa?",
  ui_story_5012_50121201_31_dialog_content = "Karena hanya kekuatan besarlah yang mampu melindungi seluruh Northland.",
  ui_story_5012_50121201_32_dialog_content = "Tapi, kekuatan... Biasanya akan mengotori hati pemiliknya, dan membuat mereka haus akan kekuatan yang lebih besar lagi.",
  ui_story_5012_50121201_33_dialog_content = "Sepanjang sejarah, sudah terlalu banyak orang yang tersesat akibat menuruti nafsu mereka untuk mengejar kekuatan yang lebih besar.",
  ui_story_5012_50121201_34_dialog_content = "Aku paham...",
  ui_story_5012_50121201_35_dialog_content = "Karenanya, meninggalkan rasa cinta diri menjadi syarat mutlak yang harus dipenuhi penerus takhta.",
  ui_story_5012_50121201_36_dialog_content = "Itu satu-satunya cara untuk membendung nafsu yang menyesatkan.",
  ui_story_5012_50121201_37_dialog_content = [[
Penerus takhta harus diuji oleh kekuatan para penguasa Northland.
Hanya dengan cara itulah, kerajaan akan mendapatkan perlindungan.]],
  ui_story_5012_50121201_38_dialog_content = "...Kurasa aku mulai lebih paham. Anda benar-benar menanggung beban seisi kerajaan di pundak Anda, Yang Mulia.",
  ui_story_5012_50121201_39_dialog_content = "Tapi aku masih tidak bisa menerima sentimen semacam ini.",
  ui_story_5012_50121201_40_dialog_content = "Mungkin karena saya tidak tumbuh di tanah air saya atau di antara orang lain seperti saya...",
  ui_story_5012_50121201_41_dialog_content = "Tapi, menurutku, mengorbankan segala yang kita kenal dan sayangi demi melindungi sepetak lahan adalah harga yang sangat mahal...",
  ui_story_5012_50121201_42_dialog_content = "Kau tak perlu memikul beban seperti ini.",
  ui_story_5012_50121201_43_dialog_content = "Tapi, yang ingin kulindungi... Itu perkara lain!",
  ui_story_5012_50121201_44_dialog_content = "Sejak meninggalkan Eraveil, aku sudah pergi ke segala penjuru dan bertemu dengan segala macam orang...",
  ui_story_5012_50121201_45_dialog_content = "Dari pertarungan paling pahit sampai hari-hari biasa yang paling tenang, aku menghargai segala yang sudah kujalani bersama mereka.",
  ui_story_5012_50121201_46_dialog_content = "Bagiku, semua pengalaman itu adalah hal paling berharga dan paling indah dalam hidupku.",
  ui_story_5012_50121201_47_dialog_content = "Dan pengalaman berharga dan indah itulah... Yang ingin kulindungi!",
  ui_story_5012_50121201_48_dialog_content = "Yang ingin kaulindungi... Jauh lebih rumit daripada Northland.",
  ui_story_5012_50121201_49_dialog_content = "Tapi, apa kau punya kekuatan untuk melakukannya?",
  ui_story_5012_50121201_50_dialog_content = "Ku... Kurasa tidak...",
  ui_story_5012_50121201_51_dialog_content = "Tapi, yang bisa kulakukan adalah... Menyatukan kekuatan semua orang!",
  ui_story_5012_50121201_52_dialog_content = [[
Sekarang, kita mungkin sudah cukup kuat, tapi suatu saat nanti...
Suatu saat nanti, kita bahkan akan lebih kuat lagi hingga bisa membalikkan roda nasib!]],
  ui_story_5012_50121201_53_dialog_content = "Begitukah?",
  ui_story_5012_50121201_54_dialog_content = "Bagiku, itu terdengar seperti renungan bocah polos dan bodoh.",
  ui_story_5012_50121201_55_dialog_content = "Dengan mentalitas seperti itu, kau tak akan pernah bisa melindungi apa pun.",
  ui_story_5012_50121201_56_dialog_content = "Aku...",
  ui_story_5012_50121201_57_dialog_content = "Berusaha melindungi terlalu banyak hal sekaligus justru hanya akan membuatmu gagal sama sekali untuk melindunginya.",
  ui_story_5012_50121201_58_dialog_content = "Coba katakan kepadaku, kenapa kau memilih untuk bersikeras pergi jauh-jauh dari Winter Palace kemari?",
  ui_story_5012_50121201_59_dialog_content = "...",
  ui_story_5012_50121201_60_dialog_content = "Demi Anda, Queen Bethlehem.",
  ui_story_5012_50121201_61_dialog_content = "Demi aku?",
  ui_story_5012_50121201_62_dialog_content = "Walaupun ini hanya ilusi, tetap saja aku merasa mengalami langsung semua ini bersama Shaya.",
  ui_story_5012_50121201_63_dialog_content = "Bagiku, pengalaman itu sama berharganya dengan semua hal lainnya.",
  ui_story_5012_50121201_64_dialog_content = "Aku tak mau melihatnya membuangnya begitu saja... Hal-hal yang menurutku berharga...",
  ui_story_5012_50121201_65_dialog_content = "Karena itulah aku bersikeras menyusul kemari... Untuk melindungi apa yang menurutku harus dilindungi!",
  ui_story_5012_50121201_66_dialog_content = "Jika tugas Anda hanya menyalakan kembali Beacon itu, berarti yang lain-lainnya bisa Anda serahkan saja kepada kami!",
  ui_story_5012_50121201_67_dialog_content = "Aku... Juga Novio...",
  ui_story_5012_50121201_68_dialog_content = "...",
  ui_story_5012_50121201_69_dialog_content = "Yang Mulia...",
  ui_story_5012_50121201_70_dialog_content = "Bersiaplah, Novio! Para Eclipsite itu makin mendekat!",
  ui_story_5012_50121201_71_dialog_content = [[
Kalau tugas sang Ratu adalah melindungi seluruh Northland...
Maka, tugas kita adalah melindungi sang Ratu!]],
  ui_story_5012_50121202_1_dialog_content = "Apa kita... Sudah sampai di Beacon?",
  ui_story_5012_50121202_2_dialog_content = "Apa kau baik-baik saja?",
  ui_story_5012_50121202_3_dialog_content = "Ya, hanya agak lelah.",
  ui_story_5012_50121202_4_dialog_content = "Perlu kugendong?",
  ui_story_5012_50121202_5_dialog_content = "Ku-Kurasa aku akan baik-baik saja, terima kasih...",
  ui_story_5012_50121202_6_dialog_content = "Awas, di belakangmu!",
  ui_story_5012_50121202_7_dialog_content = "Graaaah!!",
  ui_story_5012_50121202_8_dialog_content = "Terima kasih.",
  ui_story_5012_50121202_9_dialog_content = "Terima kasihnya nanti saja!",
  ui_story_5012_50121202_10_dialog_content = "Begitu sang Ratu berhasil menyalakan kembali obor di Beacon, ini semua akan berakhir... Iya, 'kan?",
  ui_story_5012_50121202_11_dialog_content = "Benar.",
  ui_story_5012_50121202_12_dialog_content = "Seperti apa kelihatannya saat obornya sudah kembali menyala?",
  ui_story_5012_50121202_13_dialog_content = "Seperti apa kelihatannya...? Yah, itu adalah pemandangan yang lebih indah daripada langit malam yang bertabur bintang.",
  ui_story_5012_50121202_14_dialog_content = "Begitukah? Hah, aku jadi tak sabar ingin melihatnya!",
  ui_story_5012_50121202_15_dialog_content = "Tolong selesaikan tugas Anda dan hidupkan kembali Beacon itu, Yang Mulia.",
  ui_story_5012_50121202_16_dialog_content = "Ya! Biar kami saja yang bereskan para Eclipsite ini!",
  ui_story_5012_50121202_17_dialog_content = "...",
  ui_story_5012_50121202_18_dialog_content = "(Buktikan keteguhanmu...)",
  ui_story_5012_50121202_19_dialog_content = "(Aku ingin kau membuktikannya kepadaku.)",
  ui_story_5012_50121301_1_dialog_content = "Kembali lagi ke Beacon, Putri Shaya?",
  ui_story_5012_50121301_2_dialog_content = "Aku... Aku tak mau lagi mendengarkan omongan orang-orang dewasa itu.",
  ui_story_5012_50121301_3_dialog_content = "*Mengangguk* Aku paham.",
  ui_story_5012_50121301_4_dialog_content = "Tenanglah, aku sudah meminta mereka untuk pergi.",
  ui_story_5012_50121301_5_dialog_content = "Bolehkah... Bolehkah aku tetap di sini sebentar lagi?",
  ui_story_5012_50121301_6_dialog_content = "Kau boleh tetap di sini sampai kau merasa lapar, kalau memang itu maumu. Jangan sampai melewatkan makan malam.",
  ui_story_5012_50121301_7_dialog_content = "Aku tidak lapar... Aku hanya ingin tinggal di sini selamanya...",
  ui_story_5012_50121301_8_dialog_content = "Di sini tak ada orang dewasa yang kejam... Hanya aku dan kau, Novio.",
  ui_story_5012_50121301_9_dialog_content = "Kalau memang itu keinginanmu, Lady Shaya, baiklah.",
  ui_story_5012_50121301_10_dialog_content = "Kau boleh berkunjung ke Beacon kapan pun kau merasa butuh menenangkan diri dari masalah yang kau hadapi.",
  ui_story_5012_50121301_11_dialog_content = "Baiklah...",
  ui_story_5012_50121301_12_dialog_content = "Tapi, ingatlah bahwa suatu hari nanti...",
  ui_story_5012_50121301_13_dialog_content = "Kau akan menjadi cahaya dari Beacon ini.",
  ui_story_5012_50121301_14_dialog_content = "<size=50>Graaaah!</size>",
  ui_story_5012_50121301_15_dialog_content = "Di kananmu, Novio!",
  ui_story_5012_50121301_16_dialog_content = "Kiri! Kiri lagi!",
  ui_story_5012_50121301_17_dialog_content = "*Terkesiap* Berikutnya...",
  ui_story_5012_50121301_18_dialog_content = "!!!",
  ui_story_5012_50121301_19_dialog_content = "Graaoooooohhh!!",
  ui_story_5012_50121301_20_dialog_content = "PlayerName!",
  ui_story_5012_50121301_21_dialog_content = "Kau baik-baik saja?",
  ui_story_5012_50121301_22_dialog_content = "Bukan saatnya kehilangan fokus!",
  ui_story_5012_50121301_23_dialog_content = "Aku bukannya kehilangan fokus, aku...",
  ui_story_5012_50121301_24_dialog_content = "Tiba-tiba saja aku tak bisa lagi merasakan keberadaan mereka...",
  ui_story_5012_50121301_25_dialog_content = "Aku tak bisa merasakan keberadaan satu pun Eclipsites di sekitar kita!",
  ui_story_5012_50121301_26_dialog_content = "Tak kusangka itu bisa terjadi...",
  ui_story_5012_50121301_27_dialog_content = "Apa kamu tahu penyebabnya?",
  ui_story_5012_50121301_28_dialog_content = "Tidak...",
  ui_story_5012_50121301_29_dialog_content = "Aku masih bisa merasakan Lumina, tapi Eclipsite...",
  ui_story_5012_50121301_30_dialog_content = "Mereka seolah-olah lenyap dari duniaku.",
  ui_story_5012_50121301_31_dialog_content = "Sial... Aku harus bagaimana sekarang...?",
  ui_story_5012_50121301_32_dialog_content = "Kalau kamu masih bisa merasakan Lumina, itu sudah cukup.",
  ui_story_5012_50121301_33_dialog_content = "Meski tidak bisa merasakan Eclipsite dengan kekuatanmu, tapi kamu masih bisa mengandalkan matamu yang tajam.",
  ui_story_5012_50121301_34_dialog_content = "Kamu benar!",
  ui_story_5012_50121301_35_dialog_content = "Aku... aku masih bisa terus bertarung!",
  ui_story_5012_50121301_36_dialog_content = "Hmm... Musuh berikutnya adalah...",
  ui_story_5012_50121301_37_dialog_content = "...",
  ui_story_5012_50121301_38_dialog_content = "Hei, Novio? Kerumunan besar berwarna hitam di sebelah sana... Itu kawanan Eclipsite, 'kan?",
  ui_story_5012_50121301_39_dialog_content = "Sepertinya iya... Setelah seluruh pertempuran ini, apa kamu lupa seperti apa wujud Eclipsite?",
  ui_story_5012_50121301_40_dialog_content = "Tapi, jumlah mereka terlalu banyak, 'kan?",
  ui_story_5012_50121301_41_dialog_content = "Apa kamu atau pasukanmu tidak khawatir jika melihat kawanan besar Eclipsite mengepungmu?",
  ui_story_5012_50121301_42_dialog_content = "Tidak sama sekali, kami kan punya...",
  ui_story_5012_50121301_43_dialog_content = "Iya, iya! Kalian punya ratu, 'kan?",
  ui_story_5012_50121301_44_dialog_content = "Aku sudah tahu!",
  ui_story_5012_50121301_45_dialog_content = "Yah, itu memang benar...",
  ui_story_5012_50121301_46_dialog_content = "Apa dulu Queen Bethlehem benar-benar melawan Eclipsite sebanyak ini dalam perjalanannya ke Beacon... Seorang diri?!",
  ui_story_5012_50121301_47_dialog_content = "Iya.",
  ui_story_5012_50121301_48_dialog_content = "Tapi, saat itu... umurnya tidak mungkin lebih dari sepuluh tahun!",
  ui_story_5012_50121301_49_dialog_content = "Saat berusia sepuluh tahun... Jangankan melawan Eclipsite, mengalahkan Firefly saja aku tidak bisa...",
  ui_story_5012_50121301_50_dialog_content = "Usia belum tentu sebanding dengan kekuatan sejati seseorang.",
  ui_story_5012_50121301_51_dialog_content = "Mudah sekali kamu mengatakannya!!",
  ui_story_5012_50121301_52_dialog_content = "Graaahh!",
  ui_story_5012_50121301_53_dialog_content = "Kamu dengar suara di belakang kita?",
  ui_story_5012_50121301_54_dialog_content = "Suara apa?",
  ui_story_5012_50121301_55_dialog_content = "Langkah kaki sang ratu.",
  ui_story_5012_50121301_56_dialog_content = "Ringan dan halus... Benar-benar berbeda dengan Aurorian.",
  ui_story_5012_50121301_57_dialog_content = "Mungkin kamu bisa mengetahuinya karena kamu seorang Caelestite?",
  ui_story_5012_50121301_58_dialog_content = "Memangnya langkah kakinya terdengar seperti apa bagimu?",
  ui_story_5012_50121301_59_dialog_content = "Dia berjalan di tangga, dan suara langkah kakinya perlahan-lahan makin pelan... Seperti suara jam yang berdetak.",
  ui_story_5012_50121301_60_dialog_content = "Saat mendengar suara itu, aku jadi merasa seolah-olah ratu bertarung bersama kita.",
  ui_story_5012_50121301_61_dialog_content = "Tujuannya makin dekat seiring dengan suara setiap langkahnya.",
  ui_story_5012_50121301_62_dialog_content = "Kalau begitu, kita harus bertarung hingga suara langkah kakinya berhenti. Iya, 'kan?",
  ui_story_5012_50121301_63_dialog_content = "Benar. Kamu yakin kita bisa bertahan hingga saat itu, Novio?",
  ui_story_5012_50121301_64_dialog_content = [[
Tenanglah, sebagai orang yang sudah hidup berabad-abad...
Kegigihan adalah salah satu kelebihanku.]],
  ui_story_5012_50121302_1_dialog_content = "Berapa banyak musuh yang tersisa?",
  ui_story_5012_50121302_2_dialog_content = "Apa kita... benar-benar bisa bertahan...?",
  ui_story_5012_50121302_3_dialog_content = "Tentu saja bisa.",
  ui_story_5012_50121302_4_dialog_content = "Aku yakin kekuatan mereka mulai melemah.",
  ui_story_5012_50121302_5_dialog_content = "Jumlah Eclipsite yang tersisa pasti tidak banyak.",
  ui_story_5012_50121302_6_dialog_content = "Kenapa sang Ratu belum kunjung sampai ke puncak Beacon?",
  ui_story_5012_50121302_7_dialog_content = "Apa dulu dia sudah cukup berlatih?",
  ui_story_5012_50121302_8_dialog_content = "...",
  ui_story_5012_50121302_9_dialog_content = "Meski kurasa kalau kita akan menjadi pemimpin selanjutnya, tidak banyak yang harus kita lakukan untuk diri sendiri...",
  ui_story_5012_50121302_10_dialog_content = "Awas!",
  ui_story_5012_50121302_11_dialog_content = "???",
  ui_story_5012_50121302_12_dialog_content = "Apa itu?!",
  ui_story_5012_50121302_12X1_dialog_content = "Tiba-tiba menghilang begitu saja!",
  ui_story_5012_50121302_13_dialog_content = "Eclipsite yang menyerupai manusia?",
  ui_story_5012_50121302_13X1_dialog_content = "Rasanya aku pernah melihatnya di suatu tempat...",
  ui_story_5012_50121302_13X2_dialog_content = "Benar! Aku melihatnya dalam mimpi kehancuran Eraveil!",
  ui_story_5012_50121302_14_dialog_content = "D-dan...",
  ui_story_5012_50121302_15_dialog_content = "Kurasa dia bukan Eclipsite...",
  ui_story_5012_50121302_16_dialog_content = "Bukan Eclipsite?",
  ui_story_5012_50121302_17_dialog_content = "Tapi, kehadirannya jelas-jelas tidak seperti Aurorian...",
  ui_story_5012_50121302_17X5_dialog_content = "Dia pergi lagi!",
  ui_story_5012_50121302_17X6_dialog_content = "Apa yang terjadi di sini...? Pergi ke mana dia...?",
  ui_story_5012_50121302_17X1_dialog_content = "Mimpimu akan kehancuran Eraveil adalah proyeksi dari dalam hatimu.",
  ui_story_5012_50121302_17X2_dialog_content = "Semua yang ada dalam mimpi itu ada hubungannya denganmu.",
  ui_story_5012_50121302_17X3_dialog_content = "Kenanganmu, kebencianmu, ketakutanmu...",
  ui_story_5012_50121302_17X4_dialog_content = "Coba pikirkan baik-baik. Siapakah dia?",
  ui_story_5012_50121302_18_dialog_content = "Aku tak bisa merasakannya... Ada kekuatan misterius yang mencegahku mendekat...",
  ui_story_5012_50121302_19_dialog_content = "Kamu terlalu mengandalkan kekuatanmu.",
  ui_story_5012_50121302_20_dialog_content = "Setelah kekuatan persepsi itu berkurang dan membuatmu jadi seperti manusia biasa, kamu gagal membuat penilaian paling mendasar sekalipun.",
  ui_story_5012_50121302_21_dialog_content = "Kalau terjun ke pertempuran dengan mentalitas setengah hati, cepat atau lambat kamu akan mati!",
  ui_story_5012_50121302_22_dialog_content = "PlayerName!",
  ui_story_5012_50121302_23_dialog_content = "Jangan ikut campur!",
  ui_story_5012_50121302_24_dialog_content = "Nasibmu sudah di ujung tanduk, tak ada gunanya menyembunyikannya. Saat ini, kekuatanku jauh lebih unggul darimu.",
  ui_story_5012_50121302_25_dialog_content = "(Yang memblokir kekuatanku barusan... Diakah orangnya?)",
  ui_story_5012_50121302_26_dialog_content = "(Kalau bisa fokus, mungkin aku masih punya kesempatan untuk memasuki pikiran pria ini...)",
  ui_story_5012_50121302_27_dialog_content = "(Seperti dulu...)",
  ui_story_5012_50121302_28_dialog_content = "Hei, tadi kamu sendiri yang mengatakannya: aku bukan Eclipsite.",
  ui_story_5012_50121302_29_dialog_content = "Strategi yang kamu gunakan untuk melawan Eclipsite... Kamu benar-benar mengira itu bakal mempan padaku?",
  ui_story_5012_50121302_30_dialog_content = "(Apa-apaan pria ini...?)",
  ui_story_5012_50121302_31_dialog_content = "<size=45>(Bagaimana menurutmu?)</size>",
  ui_story_5012_50121302_32_dialog_content = "<size=45>?!?</size>",
  ui_story_5012_50121302_33_dialog_content = "Sebentar... Dia justru memasuki pikiranku?!",
  ui_story_5012_50121302_34_dialog_content = "Ada apa? Sedih karena orang lain bisa melakukannya dengan lebih baik? Rupanya kamu memang tidak sehebat itu, ya?",
  ui_story_5012_50121302_35_dialog_content = "Aku paham... Kamu...",
  ui_story_5012_50121302_36_dialog_content = "Kita memiliki kekuatan yang sama...",
  ui_story_5012_50121302_37_dialog_content = "Berarti, kamu bukan Aurorian maupun Eclipsite...",
  ui_story_5012_50121302_38_dialog_content = "<size=45>Kamu Caelestite!</size>",
  ui_story_5012_50121302_39_dialog_content = "Sudah tahu, ya? Lamban juga kamu, tapi tidak selamban yang kuduga.",
  ui_story_5012_50121302_40_dialog_content = "Tapi, kenapa kamu punya kekuatan semacam ini juga?",
  ui_story_5012_50121302_41_dialog_content = "Kukira Caelestite...",
  ui_story_5012_50121302_42_dialog_content = "Apa? Lemah? Tak berdaya? Hanya bisa bersembunyi di belakang Aurorian yang lebih kuat, seperti kamu?",
  ui_story_5012_50121302_43_dialog_content = "Tidak... Caelestite jauh lebih hebat dari perkiraanmu.",
  ui_story_5012_50121302_44_dialog_content = "Nah, katakan, menurutmu seperti apa kita sebenarnya?",
  ui_story_5012_50121302_45_dialog_content = "Dengan kemampuan dasar untuk merasakan dan melihat Lumina, Aurorian seolah-olah buta jika dibandingkan dengan kita.",
  ui_story_5012_50121302_46_dialog_content = "Sayangnya, semua ada harganya, dan harga untuk penglihatan superior kita adalah ketidakmampuan untuk mengendalikan Lumina.",
  ui_story_5012_50121302_47_dialog_content = "Tapi, tidakkah kamu penasaran? Apa jadinya kalau kita BISA memiliki kekuatan seperti Aurorian?",
  ui_story_5012_50121302_48_dialog_content = "...",
  ui_story_5012_50121302_49_dialog_content = "Selain itu, apa jadinya kalau kita punya kekuatan Eclipsite?",
  ui_story_5012_50121302_50_dialog_content = "Kamu terlalu rakus!",
  ui_story_5012_50121302_51_dialog_content = "Rakus? Tidak, mencari kekuatan tidak bisa disebut \"rakus\".",
  ui_story_5012_50121302_52_dialog_content = "Anak kecil belajar di sekolah, atau serdadu berlatih cara bertempur... Keduanya berusaha memiliki kekuatan yang lebih besar.",
  ui_story_5012_50121302_53_dialog_content = "Kamu sebut itu \"rakus\" juga?",
  ui_story_5012_50121302_54_dialog_content = "Itu sama sekali berbeda!",
  ui_story_5012_50121302_55_dialog_content = "Kamu salah! Kekuatan itu murni, tahu?",
  ui_story_5012_50121302_56_dialog_content = "Pelajaran yang ditawarkannya pun cukup mudah!",
  ui_story_5012_50121302_57_dialog_content = "Misalnya, sekarang! Tanpa kekuatan, riwayatmu dan temanmu akan tamat.",
  ui_story_5012_50121302_58_dialog_content = "Perjuanganmu hingga saat ini, dan tekad yang kamu tunjukkan pada ratu... Semuanya akan menjadi tak bermakna.",
  ui_story_5012_50121302_59_dialog_content = "Bagaimana? Kamu setuju?",
  ui_story_5012_50121302_60_dialog_content = "...",
  ui_story_5012_50121302_61_dialog_content = "Tapi, kamu punya pilihan lain.",
  ui_story_5012_50121302_62_dialog_content = "Aku bisa memberitahumu cara mendapatkan kekuatan yang lebih besar.",
  ui_story_5012_50121302_63_dialog_content = "...",
  ui_story_5012_50121302_64_dialog_content = "Bisakah kamu merasakan pedangku yang menyentuh kulitmu?",
  ui_story_5012_50121302_65_dialog_content = "Kamu punya waktu untuk menjawabnya hingga pedangku menembus tubuhmu.",
  ui_story_5012_50121302_66_dialog_content = "Kuharap jawabanmu benar...",
  ui_story_5012_50121302_67_dialog_content = "Kurasa... Ada yang salah.",
  ui_story_5012_50121302_68_dialog_content = "Apa kesalahanku...?",
  ui_story_5012_50121302_69_dialog_content = "Aku memang akan kalah jika tidak punya kekuatan.",
  ui_story_5012_50121302_70_dialog_content = "Tapi, masalahnya... aku tidak takut gagal.",
  ui_story_5012_50121302_71_dialog_content = "Tidak takut gagal?",
  ui_story_5012_50121302_72_dialog_content = "Orang akan selalu menginginkan lebih kalau selalu menang.",
  ui_story_5012_50121302_73_dialog_content = "Tapi, bagiku... Kemenangan tidak ada artinya.",
  ui_story_5012_50121302_74_dialog_content = "Omong kosong! Apa lagi yang tersisa kalau kamu kalah?",
  ui_story_5012_50121302_75_dialog_content = "Kamu akan mati! Kamu tak akan punya apa-apa!",
  ui_story_5012_50121302_76_dialog_content = "Akan kuterima apa pun hasilnya setelah berusaha sekuat tenaga.",
  ui_story_5012_50121302_77_dialog_content = "\"Terima\"...? Kamu sanggup membayar harga kegagalan?",
  ui_story_5012_50121302_78_dialog_content = "Alasanku selalu mencoba jadi lebih kuat adalah agar aku bisa menerimanya.",
  ui_story_5012_50121302_79_dialog_content = "Selain itu... aku tidak sendirian.",
  ui_story_5012_50121302_80_dialog_content = "Kalau gagal, aku selalu bisa menyerahkannya kepada teman-temanku, dan orang-orang lain yang bisa kuandalkan.",
  ui_story_5012_50121302_81_dialog_content = "Dan mereka tak pernah mengecewakanku.",
  ui_story_5012_50121302_82_dialog_content = "Aku ingin melindungi teman-temanku, dan begitu juga sebaliknya dengan mereka!",
  ui_story_5012_50121302_83_dialog_content = "Konyol!",
  ui_story_5012_50121302_84_dialog_content = "Tak kusangka orang bodoh yang keras kepala seperti kamu hanya mengandalkan keberuntungan untuk bertahan hidup!",
  ui_story_5012_50121302_85_dialog_content = "Ini bukan hanya soal keberuntungan.",
  ui_story_5012_50121302_86_dialog_content = "Kalau kau memang Caelestite seperti aku, kau pasti juga bisa mendengar suara dari dalam Beacon itu.",
  ui_story_5012_50121302_87_dialog_content = "...",
  ui_story_5012_50121302_88_dialog_content = "Aku tidak mendengar suara apa pun dari Beacon.",
  ui_story_5012_50121302_89_dialog_content = "Kamu benar. Memang tak ada suara sama sekali.",
  ui_story_5012_50121302_90_dialog_content = "Berarti langkah kaki di tangga... Akhirnya berhenti.",
  ui_story_5012_50121302_91_dialog_content = "!!!",
  ui_story_5012_50121302_92_dialog_content = "Ratu telah mencapai puncak Beacon.",
  ui_story_5012_50121302_92X1_dialog_content = "Suarnya akan segera dinyalakan sebagai pertanda bahwa Sanctuary yang mengawasi Northland telah didirikan kembali.",
  ui_story_5012_50121302_92X2_dialog_content = "Jika Novio benar, Sanctuary akan menghancurkan semua Eclipsites.",
  ui_story_5012_50121302_93_dialog_content = "Semua sudah berakhir.",
  ui_story_5012_50121302_94_dialog_content = "Apa?!",
  ui_story_5012_50121302_95_dialog_content = "Aku... aku sama sekali tak bisa bergerak...",
  ui_story_5012_50121302_96_dialog_content = "Sepertinya inilah batas kekuatan yang sangat kamu banggakan itu.",
  ui_story_5012_50121302_97_dialog_content = "Di hadapan kekuatan yang lebih besar, hal-hal yang kamu kejar terlihat jauh lebih tidak penting, 'kan?",
  ui_story_5012_50121302_98_dialog_content = "Nah, sekarang saatnya kamu menghadapi kegagalanmu.",
  ui_story_5012_50121302_99_dialog_content = "Musuh sekuat itu tiba-tiba hilang...",
  ui_story_5012_50121302_100_dialog_content = "Ini Northland, Lord PlayerName. Tak seorang pun bisa mengalahkan kekuatan ratu kami.",
  ui_story_5012_50121302_101_dialog_content = "Kamu baik-baik saja, Novio...?",
  ui_story_5012_50121302_102_dialog_content = "Aku tidak apa-apa.",
  ui_story_5012_50121302_103_dialog_content = "Biasanya, pertarungan ini tak akan terlalu melelahkan...",
  ui_story_5012_50121302_104_dialog_content = "Tapi, setelah berada di sisi ratu selama bertahun-tahun, aku jadi agak tidak terbiasa dengan pertempuran.",
  ui_story_5012_50121302_105_dialog_content = "Bagus... Ada lebih banyak Eclipsite yang menuju kemari.",
  ui_story_5012_50121302_106_dialog_content = "Benar...",
  ui_story_5012_50121302_107_dialog_content = "Mereka akan jadi persembahan yang cocok untuk penobatan ratu baru kami.",
  ui_story_5012_50121302_108_dialog_content = "Kedengarannya agak tidak menyenangkan...",
  ui_story_5012_50121302_109_dialog_content = "Lihat ke sana.",
  ui_story_5012_50121302_110_dialog_content = "Akhirnya, matahari terbit.",
  ui_story_5012_50121302_111_dialog_content = "Beacon dan fajar...",
  ui_story_5012_50121302_112_dialog_content = "Dua sumber cahaya yang berbeda, tetapi sama-sama bersinar dalam gelapnya malam.",
  ui_story_5012_50121302_113_dialog_content = "Pada hari pertama Polar Night, kita hanya melihat cahaya matahari sebentar saja... Dan inilah saat itu.",
  ui_story_5012_50121302_114_dialog_content = "Kita tidak bisa melihat matahari di waktu-waktu seperti ini; hanya ada cahaya yang bersinar dalam kegelapan selama beberapa detik.",
  ui_story_5012_50121302_115_dialog_content = "Tapi, penduduk Northland akan selalu memandang cakrawala dengan penuh semangat, menanti datangnya fajar yang paling singkat ini.",
  ui_story_5012_50121302_116_dialog_content = "Mereka terjaga pada malam terpanjang dalam setahun untuk menyambut saat yang singkat ini.",
  ui_story_5012_50121302_117_dialog_content = "Karena setelah hari ini, perlahan-lahan kami bisa melihat lebih banyak siang hari.",
  ui_story_5012_50121302_118_dialog_content = [[
Kehidupan bangkit kembali di negeri membeku kami,
Saat Northland menyambut tahun baru.]],
  ui_story_5012_50121302_119_dialog_content = "Aku juga sangat berharap semua orang bisa melihatnya denganku...",
  ui_story_5012_50121302_120_dialog_content = "Kamu akan melihatnya bersama mereka... Suatu saat nanti.",
  ui_story_5012_50121302_121_dialog_content = "Cerita di sini telah berakhir, dan ilusi ini akan memudar.",
  ui_story_5012_50121302_122_dialog_content = "Ayo kita kembali ke kenyataan dan menikmati Tahun Baru.",
  ui_story_5012_50121401_1_dialog_content = "Ah! Lihat ke sebelah sana!",
  ui_story_5012_50121401_2_dialog_content = "Bisa-bisanya kau tiba-tiba pergi ke Lake Mirror seperti itu?",
  ui_story_5012_50121401_3_dialog_content = "Kalau tidak bergegas, nanti kamu akan melewatkan upacara Tahun Baru!",
  ui_story_5012_50121401_4_dialog_content = "Carleen, Vice... Wah, ada Lola juga...",
  ui_story_5012_50121401_5_dialog_content = "Apa aku sudah kembali ke dunia nyata?",
  ui_story_5012_50121401_6_dialog_content = "Bicara apa kamu?",
  ui_story_5012_50121401_7_dialog_content = "Ke mana saja kamu dari tadi?",
  ui_story_5012_50121401_8_dialog_content = "Meski tidak ada Eclipsite di Northland, jangan sampai lengah.",
  ui_story_5012_50121401_9_dialog_content = "Kamu melewatkan banyak hal, PlayerName! Kenapa lama sekali, sih?",
  ui_story_5012_50121401_10_dialog_content = "Kami baru saja kembali dari pasar. Mereka menjual berbagai barang dan makanan yang menarik, lo!",
  ui_story_5012_50121401_11_dialog_content = "Makanan di Northland sangat lezat! Pokoknya kamu harus mencicipi bola daging goreng yang dicelup saus stroberi. Rasanya enak sekali!",
  ui_story_5012_50121401_12_dialog_content = "Setelah kita pulang nanti, aku akan memasaknya untuk semua orang!",
  ui_story_5012_50121401_13_dialog_content = "S-sepertinya aku memang melewatkan hal-hal yang mengasyikkan...",
  ui_story_5012_50121401_14_dialog_content = "Cepat! Kita harus kembali ke Winter Palace!",
  ui_story_5012_50121401_15_dialog_content = "Masih ada sesuatu yang harus kusampaikan pada ratu...",
  ui_story_5012_50121401_16_dialog_content = "Eh...? Y-Yang Mulia!!",
  ui_story_5012_50121401_17_dialog_content = "Apa kamu menikmati perayaan tahun ini, Lola?",
  ui_story_5012_50121401_18_dialog_content = "Iya! Aku senang sekali!",
  ui_story_5012_50121401_19_dialog_content = "Aku tak mengira akan bertemu Yang Mulia di sini...",
  ui_story_5012_50121401_20_dialog_content = "Apakah Anda yang mengundang PlayerName kemari?",
  ui_story_5012_50121401_21_dialog_content = "Benar sekali.",
  ui_story_5012_50121401_22_dialog_content = "Kupikir ada yang aneh dengan undangan yang kami terima tadi.",
  ui_story_5012_50121401_23_dialog_content = "Setahuku, Northland jarang mencoba melakukan kontak dengan dunia luar, apalagi mengundang orang luar untuk merayakan tahun baru.",
  ui_story_5012_50121401_24_dialog_content = "Apakah ada masalah mendesak yang ingin Anda bahas dengan PlayerName?",
  ui_story_5012_50121401_25_dialog_content = "Kami pergi untuk memandang Lake Mirror bersama-sama.",
  ui_story_5012_50121401_26_dialog_content = "Aku menemukan <color=#FFB400>jawaban</color> yang kucari di dalam perairan danau itu.",
  ui_story_5012_50121401_27_dialog_content = "Di dalam air...?",
  ui_story_5012_50121401_28_dialog_content = "Apa kamu juga berhasil menemukan jawabannya, Caelestite?",
  ui_story_5012_50121401_29_dialog_content = "Ada... ada satu hal yang ingin hamba tanyakan.",
  ui_story_5012_50121401_30_dialog_content = "Musuh terakhir yang kita hadapi, Caelestite yang kuat itu...",
  ui_story_5012_50121401_31_dialog_content = "Apa dia juga benar-benar muncul di medan tempur bertahun-tahun lalu?",
  ui_story_5012_50121401_32_dialog_content = "Tidak.",
  ui_story_5012_50121401_33_dialog_content = "Musuh semacam itu belum muncul di dunia.",
  ui_story_5012_50121401_34_dialog_content = "Dia hanyalah fatamorgana, ilusi yang terlihat dari dalam pecahan masa depan yang hancur.",
  ui_story_5012_50121401_35_dialog_content = "Akhir yang menyedihkan untuk seorang Caelestite yang mencari kekuatan lebih besar.",
  ui_story_5012_50121401_36_dialog_content = "Baiklah... Aku paham sekarang.",
  ui_story_5012_50121401_37_dialog_content = "Kamu telah membuktikan tekadmu.",
  ui_story_5012_50121401_38_dialog_content = "Tapi, meski begitu, dia mengalahkanmu hari ini.",
  ui_story_5012_50121401_39_dialog_content = "Apa kamu merasa sedih?",
  ui_story_5012_50121401_40_dialog_content = "Tidak sama sekali.",
  ui_story_5012_50121401_41_dialog_content = "Hamba tak pernah menganggap diri lebih lemah dari dia.",
  ui_story_5012_50121401_42_dialog_content = "Di situasi yang buruk itu, kami memang sudah mengira akan kalah...",
  ui_story_5012_50121401_43_dialog_content = "Tapi, sekarang, asalkan ada teman-teman di sisi hamba...",
  ui_story_5012_50121401_44_dialog_content = "Dia tak akan pernah menang melawan hamba!",
  ui_story_5012_50121401_45_dialog_content = "Jawabanmu selalu sangat menarik.",
  ui_story_5012_50121401_46_dialog_content = "Mau membuktikannya padaku?",
  ui_story_5012_50121401_47_dialog_content = "Buktikan mana yang lebih kuat: Caelestite tanpa kekuatan atau Caelestite yang tak pernah berhenti mencarinya?",
  ui_story_5012_50121401_48_dialog_content = "Tentu saja hamba akan membuktikannya kepada Anda!",
  ui_story_5012_50121401_49_dialog_content = "Tapi, bagaimana cara melakukannya...",
  ui_story_5012_50121401_50_dialog_content = "Hah?!?",
  ui_story_5012_50121401_51_dialog_content = "A-Anda bisa menciptakan yang seperti ini di dunia nyata?!",
  ui_story_5012_50121401_52_dialog_content = "Kemarilah, semuanya; waktunya pertarungan bola salju yang belum pernah ada sebelumnya.",
  ui_story_5012_50121401_53_dialog_content = "Pertarungan bola salju? Aku ikut!",
  ui_story_5012_50121401_54_dialog_content = "Bersiaplah makan es! Ayo, teman-teman!",
  ui_story_5012_50121402_1_dialog_content = "Sudah selesai...",
  ui_story_5012_50121402_2_dialog_content = "*Terengah-engah* Ini... ini bukan pertarungan bola salju biasa!",
  ui_story_5012_50121402_3_dialog_content = "Ini karena ilusi ratu sangat kuat... Dia benar-benar lebih hebat dari semua orang.",
  ui_story_5012_50121402_4_dialog_content = "Selama kurun waktu singkat yang kuhabiskan di Northland saat masih kecil, ratu menggunakan ilusi serupa untuk menciptakan musuh sebagai lawan berlatihku.",
  ui_story_5012_50121402_5_dialog_content = "Setelah bertahun-tahun kemudian, kupikir aku sudah jadi lebih kuat dari sebelumnya...",
  ui_story_5012_50121402_6_dialog_content = "Tapi, setelah menghadapi ratu sekali lagi, rasanya hampir tidak ada yang berubah...",
  ui_story_5012_50121402_7_dialog_content = "Rasakan ini! Hah! Biar kamu jera!",
  ui_story_5012_50121402_8_dialog_content = "H-hati-hati, Lola!",
  ui_story_5012_50121402_9_dialog_content = "Aku baik-baik saja!",
  ui_story_5012_50121402_10_dialog_content = "Ini kan hanya manusia salju besar yang dibuat ratu? Memangnya semenakutkan apa, sih?",
  ui_story_5012_50121402_11_dialog_content = "Bukan situasinya yang jadi masalah, tapi kalau kamu masuk angin.",
  ui_story_5012_50121402_12_dialog_content = "Oh, baiklah...",
  ui_story_5012_50121402_13_dialog_content = "Selalu saja ada yang kamu cemaskan, Novio.",
  ui_story_5012_50121402_14_dialog_content = "Ini bukan pertama kalinya kamu masuk angin gara-gara terlalu sembrono saat bermain salju.",
  ui_story_5012_50121402_15_dialog_content = "Saat itu aku masih kecil! Tapi, sekarang...",
  ui_story_5012_50121402_16_dialog_content = "H-hei! Lihat ke atas, teman-teman!",
  ui_story_5012_50121402_17_dialog_content = "Indahnya...",
  ui_story_5012_50121402_18_dialog_content = "Wow!",
  ui_story_5012_50121402_19_dialog_content = "Sudah lama sekali aku tidak melihat aurora seperti ini...",
  ui_story_5012_50121402_20_dialog_content = "Northland benar-benar tempat yang ajaib. Bahkan dalam gelapnya malam, tubuhku dikelilingi Lumina yang terang...",
  ui_story_5012_50121402_21_dialog_content = "Apa hanya Lumina saja yang kamu dan Caelestite lain pikirkan, PlayerName?",
  ui_story_5012_50121402_22_dialog_content = "Gunakan matamu sebentar saja, dan lihatlah pemandangan indah ini...",
  ui_story_5012_50121402_23_dialog_content = "Iya... Indah sekali.",
  ui_story_5012_50121402_24_dialog_content = "Kehidupan di Northland memang sederhana dan sedikit membosankan.",
  ui_story_5012_50121402_25_dialog_content = "Tapi, di tempat inilah banyak orang memiliki kenangan yang menyenangkan.",
  ui_story_5012_50121402_26_dialog_content = "Mungkin itu karena keindahan negeri ini sulit digantikan dengan pemandangan dari dunia lain.",
  ui_story_5012_50121402_27_dialog_content = "Hmph, kamu sengaja mengatakannya hanya agar aku bisa mendengarnya, 'kan?",
  ui_story_5012_50121402_28_dialog_content = "Aku hanya bicara kepada siapa pun yang mau mendengar, kok.",
  ui_story_5012_50121402_29_dialog_content = "Iya, iya, aku paham! Bukannya aku sudah berjanji akan kembali kemari setidaknya sekali dalam setahun?",
  ui_story_5012_50121402_30_dialog_content = "Eh... Aduh! Aku sampai lupa waktu!",
  ui_story_5012_50121402_31_dialog_content = "Cepat! Kembali ke Winter Palace! Masih ada banyak hal yang harus dikerjakan!",
  ui_story_5012_50121402_32_dialog_content = "H-hei, aku tahu, kok! Jangan tarik-tarik aku seperti ini, dong!",
  ui_story_5012_50121402_33_dialog_content = "Bisa-bisanya kamu tidak bersemangat! Ini pasti akan sangat menyenangkan!",
  ui_story_5012_50121402_34_dialog_content = [[
Tunggu saja! Pakaian indah, banyak makanan...
Dan semua orang menyanyikan lagu-lagu penuh syukur di Winter Palace!]],
  ui_story_5012_50121402_35_dialog_content = "Eh, b-baiklah... Pelan-pelan sedikit, ya..?.",
  ui_story_5012_50121402_36_dialog_content = "Benar juga! Kamu belum bisa menyanyikan lagu-lagu yang penuh syukur, 'kan?",
  ui_story_5012_50121402_37_dialog_content = "Ayo kita luangkan waktu untuk mempelajari beberapa!",
  ui_story_5012_50121402_38_dialog_content = "\"Kerajaan utara, ibu kami yang murah hati...♪\"",
  ui_story_5012_50121402_39_dialog_content = "Ayo, nyanyikan bersama!",
  ui_story_5012_50121402_40_dialog_content = "<anim type=Shake>B-bagaimana... Caranya... Kamu bisa... Berlari... Sambil... Bernyanyi...?</anim>",
  ui_story_5012_50121402_41_dialog_content = "<anim type=Shake>Berlari... Atau Bernyanyi... Tolong... Pilih salah satu saja...!</anim>",
  ui_story_5012_50121402_42_dialog_content = "Oh, satu hal lagi!",
  ui_story_5012_50121402_43_dialog_content = "<anim type=Shake>T-tolong... Kasihanilah aku...</anim>",
  ui_story_5012_50121402_44_dialog_content = "Jangan lupa menyiapkan kado Tahun Baru juga, ya!",
  ui_story_5012_50121501_1_dialog_content = "...",
  ui_story_5012_50121501_2_dialog_content = "Yang Mulia.",
  ui_story_5012_50121501_3_dialog_content = "Anda baik-baik saja?",
  ui_story_5012_50121501_4_dialog_content = "Sudah berapa lama... aku berdiri di sini?",
  ui_story_5012_50121501_5_dialog_content = "Sepuluh menit.",
  ui_story_5012_50121501_6_dialog_content = "Anak-anak sudah kembali.",
  ui_story_5012_50121501_7_dialog_content = "Aku tahu.",
  ui_story_5012_50121501_8_dialog_content = "Bolehkah aku bertanya... Apa yang ingin Anda lihat kali ini di perairan Lake Mirror?",
  ui_story_5012_50121501_9_dialog_content = "Masa depan.",
  ui_story_5012_50121501_10_dialog_content = "Dalam sisa-sisa penglihatan yang kulihat sebelumnya, selalu ada Caelestite itu di setiap masa depan yang bisa kulihat.",
  ui_story_5012_50121501_11_dialog_content = "Dialah yang bisa membentuk kembali masa depan.",
  ui_story_5012_50121501_12_dialog_content = "Tapi, persepsiku tentang dia selalu sedikit salah.",
  ui_story_5012_50121501_13_dialog_content = "Atau lebih tepatnya, pemikiran dan pandangannya selalu jauh di luar imajinasiku.",
  ui_story_5012_50121501_14_dialog_content = "Untuk alasan ini, aku tak bisa melihat masa depan yang telah dia bentuk kembali.",
  ui_story_5012_50121501_15_dialog_content = "Tapi, bisakah Anda melihatnya sekarang?",
  ui_story_5012_50121501_16_dialog_content = "Iya.",
  ui_story_5012_50121501_17_dialog_content = "Aku jadi penasaran akan seperti apa masa depan ini.",
  ui_story_5012_50121501_18_dialog_content = "Ini akan jadi masa depan yang tak seperti apa pun yang telah kamu lihat selama bertahun-tahun, Novio.",
  ui_story_5012_50121501_19_dialog_content = "Tak seperti apa pun yang telah kulihat...",
  ui_story_5012_50121501_20_dialog_content = "Tapi, untuk sementara itu sudah cukup.",
  ui_story_5012_50121501_21_dialog_content = "Orang-orang sudah menunggu kita di Winter Palace.",
  ui_story_5012_50121501_22_dialog_content = "Kamu boleh pergi, Novio.",
  ui_story_5012_50121501_23_dialog_content = "...",
  ui_story_5012_50121501_24_dialog_content = "Baik, Yang Mulia.",
  ui_story_5012_50121501_25_dialog_content = "Lonceng, pita, dan benang sutra biru...",
  ui_story_5012_50121501_26_dialog_content = "Tapi, kenapa rasanya masih ada yang kurang, ya? Biar kulihat lagi daftar belanjaan itu...",
  ui_story_5012_50121501_27_dialog_content = "Aaaahh! Sial, lagi-lagi aku lupa membeli bintang untuk pohon kelipnya! Itu kan benda yang paling penting!",
  ui_story_5012_50121501_28_dialog_content = "<size=30>Sebentar... Lupa \"lagi\"?</size>",
  ui_story_5012_50121501_29_dialog_content = "Kalau ada orang yang sampai tahu, Novio pasti akan terus mengomeliku...",
  ui_story_5012_50121501_30_dialog_content = "<size=30>Aku harus mencari alasan agar bisa kembali ke pasar...</size>",
  ui_story_5012_50121501_31_dialog_content = "Lola? Apakah kamu sedang mencari sesuatu?",
  ui_story_5012_50121501_32_dialog_content = "<size=45>T-tidak, kok!</size>",
  ui_story_5012_50121501_33_dialog_content = "Aku... aku mau menghias pohon kelipnya sekarang!",
  ui_story_5012_50121501_34_dialog_content = "Oh, butuh bantuan tidak? Tadi kudengar kamu...",
  ui_story_5012_50121501_35_dialog_content = "Kami mau mengantar PlayerName melihat-lihat pasar. Mau menitip sesuatu?",
  ui_story_5012_50121501_X33_dialog_content = "Kami mau melihat-lihat pasar. Mau menitip sesuatu?",
  ui_story_5012_50121501_X34_dialog_content = "Aku belum sempat ke pasar.",
  ui_story_5012_50121501_36_dialog_content = "B-benarkah?! Oh, kalian memang pahlawanku!",
  ui_story_5012_50121501_37_dialog_content = "Kalau tidak keberatan, bisakah kalian membeli bintang untuk pohon kelip saat di pasar nanti?",
  ui_story_5012_50121501_38_dialog_content = "Tentu saja, tapi... Seperti apa bentuknya?",
  ui_story_5012_50121501_39_dialog_content = "Hmm... Kalian bisa membelinya di toko kedua di kanan jalan setibanya di pasar.",
  ui_story_5012_50121501_40_dialog_content = "Bilang saja kepada pemilik toko itu bahwa kalian butuh bintang pohon hari raya yang superbesar. Dia tahu yang mana barangnya!",
  ui_story_5012_50121501_X40_dialog_content = "Baiklah, ayo kita berangkat sekarang.",
  ui_story_5012_50121501_X41_dialog_content = "Vice dan aku akan membantu menghias Winter Palace. Tidak apa-apa kalau kamu pergi sendiri, 'kan?",
  ui_story_5012_50121501_X42_dialog_content = "Hah? Kita tidak jadi pergi bersama-sama?",
  ui_story_5012_50121501_X43_dialog_content = "Apa? Bukannya kita juga mau pergi?",
  ui_story_5012_50121501_X44_dialog_content = "Terakhir kalinya ke sana, kamu hampir memborong seisi pasar kalau kami tidak mencegahmu.",
  ui_story_5012_50121501_X45_dialog_content = "Hei! Aku kan hanya ingin membeli oleh-oleh untuk semua orang!",
  ui_story_5012_50121501_X46_dialog_content = "Tapi, ada sesuatu yang lupa kubeli... PlayerName, bisakah kamu membelinya kalau sempat?",
  ui_story_5012_50121501_X47_dialog_content = "Memangnya kamu mau beli apa?",
  ui_story_5012_50121501_X48_dialog_content = "Tiga ukiran rusa kayu kecil dari toko ketiga di kiri jalan...",
  ui_story_5012_50121501_X49_dialog_content = "Nah, di toko keempat di kanan jalan, ada satu boneka manusia salju kecil bersyal merah dan dua boneka manusia salju berukuran sedang bertopi kecil, dan...",
  ui_story_5012_50121501_X50_dialog_content = "Tunggu! Bagaimana aku bisa mengingat semua itu?",
  ui_story_5012_50121501_X51_dialog_content = "Bisa-bisanya kamu bisa mengingat itu semua!?",
  ui_story_5012_50121501_X52_dialog_content = "Biar kuulangi sekali lagi.",
  ui_story_5012_50121501_X53_dialog_content = "Carleen, pergilah duluan untuk membantu Lola memasang lampu. Aku susul sebentar lagi.",
  ui_story_5012_50121501_X54_dialog_content = "Baiklah, aku pergi dulu.",
  ui_story_5012_50121501_X55_dialog_content = "Jangan lupa, pikir-pikir dulu sebelum belanja.",
  ui_story_5012_50121501_X56_dialog_content = "Iya, iya!",
  ui_story_5012_50121501_X57_dialog_content = "... Aku cari pulpen dan kertas dulu.",
  ui_story_5012_50121501_X58_dialog_content = "Sudahlah, kamu tak perlu membelinya.",
  ui_story_5012_50121501_X59_dialog_content = "Hah? Kamu tidak jadi membelinya?",
  ui_story_5012_50121501_X60_dialog_content = "Pita biru... Beli itu saja.",
  ui_story_5012_50121501_41_dialog_content = "Toko kedua di kanan jalan... Ini tempatnya, 'kan?",
  ui_story_5012_50121501_X61_dialog_content = "Selamat Tahun Baru, Tuan. Ada yang bisa kubantu?",
  ui_story_5012_50121501_X62_dialog_content = "Halo, aku mau membeli bintang kayu superbesar.",
  ui_story_5012_50121501_X63_dialog_content = "Ini dia—sudah siap.",
  ui_story_5012_50121501_X64_dialog_content = "Terima kasih.",
  ui_story_5012_50121501_X65_dialog_content = "Anu, maaf atas kelancanganku, tapi apa Nona Lola tidak datang tahun ini?",
  ui_story_5012_50121501_X66_dialog_content = "Dia datang. Sekarang dia sedang menghias pohon kelip di Winter Palace.",
  ui_story_5012_50121501_X67_dialog_content = "Sungguh suatu kehormatan bisa membuat bintang kayu untuk Winter Palace! Tolong sampaikan salamku untuk Lola dan Her Majesty!",
  ui_story_5012_50121501_X68_dialog_content = "Tentu saja.",
  ui_story_5012_50121501_X69_dialog_content = "Anu... apa ada pita biru?",
  ui_story_5012_50121501_X70_dialog_content = "Tentu saja! Ada yang lain? Biar kumasukkan sekaligus ke dalam kantong.",
  ui_story_5012_50121501_42_dialog_content = "Halo, Nona! Ada yang bisa kubantu hari ini?",
  ui_story_5012_50121501_43_dialog_content = "Kami mencari... Bintang superbesar untuk pohon kelip.",
  ui_story_5012_50121501_44_dialog_content = "Hmm... Kamu harus menunggu sebentar. Bintang seukuran itu harus dibuat langsung, tapi tidak butuh waktu lama, kok.",
  ui_story_5012_50121501_45_dialog_content = "Kalau begitu, bolehkah kami membeli barang lain dulu sambil menunggu? Kami akan kembali setelah bintangnya selesai dibuat.",
  ui_story_5012_50121501_46_dialog_content = "Bukan masalah!",
  ui_story_5012_50121501_47_dialog_content = "Wow, lihat ke sana! Apa kamu pernah melihat pita semungil ini?",
  ui_story_5012_50121501_48_dialog_content = "Sepertinya aku harus membeli beberapa untuk kupakaikan pada para Firefly! Imut sekali, 'kan, PlayerName?",
  ui_story_5012_50121501_49_dialog_content = "Hah? PlayerName? Aduh, pergi ke mana lagi dia kali ini?!",
  ui_story_5012_50121501_50_dialog_content = "P-permisi, anu... Apa ini?",
  ui_story_5012_50121501_51_dialog_content = "Selamat Tahun Baru, kawan.",
  ui_story_5012_50121501_52_dialog_content = "Ini jam pasir, untuk melihat jam. Ini barang spesial buatan keluarga kami dari generasi ke generasi.",
  ui_story_5012_50121501_53_dialog_content = "\"Meski waktu mungkin berlalu tanpa akhir, masa lalu dan masa depan akan selalu ada di tanganmu.\" Itulah arti dari jam pasir.",
  ui_story_5012_50121501_54_dialog_content = "Sepertinya kamu tidak berasal dari sekitar sini, kawan. Bagaimana kalau kamu membelinya sebagai suvenir, dan memberikannya kepada temanmu sebagai hadiah?",
  ui_story_5012_50121501_55_dialog_content = "Tentu, aku mau beli satu. Tolong sekalian dibungkus.",
  ui_story_5012_50121501_56_dialog_content = "Di situ kamu rupanya, PlayerName! Aku sudah mencarimu ke mana-mana!",
  ui_story_5012_50121501_57_dialog_content = "Lihat ini! Belanjaanku lumayan juga, 'kan?",
  ui_story_5012_50121501_58_dialog_content = "... Kamu benar-benar harus membeli sebanyak itu?!",
  ui_story_5012_50121501_59_dialog_content = "Ini belanja kedua kita. Kalau Vice punya lebih banyak tangan atau gerobak, dia pasti sudah memborong seisi pasar...",
  ui_story_5012_50121501_60_dialog_content = "Tapi, mana mungkin kulewatkan hiasan kecil dan imut semacam ini?!",
  ui_story_5012_50121501_61_dialog_content = "... Pohon kelip itu pasti sudah selesai dihias. Sebaiknya kita kembali.",
  ui_story_5012_50121501_62_dialog_content = "Benar, sebentar lagi gelap... Kita harus segera kembali ke Winter Palace.",
  ui_story_5012_50121501_63_dialog_content = "Kamu beli apa, PlayerName?",
  ui_story_5012_50121501_64_dialog_content = "Oh, hanya hadiah kecil.",
  ui_story_5012_50121501_X71_dialog_content = "Aku pulang.",
  ui_story_5012_50121501_X72_dialog_content = "Wah, kamu sudah kembali, PlayerName.",
  ui_story_5012_50121501_X73_dialog_content = "Ah, sebenarnya... kamu tidak perlu menjemputku.",
  ui_story_5012_50121501_X74_dialog_content = "Winter Palace ini sangat besar. Kamu yakin bisa menemukan aula utama sendirian?",
  ui_story_5012_50121501_X75_dialog_content = "... Aku menghargai kebaikanmu.",
  ui_story_5012_50121501_65_dialog_content = "Maaf karena membuatmu menunggu, Master Novio.",
  ui_story_5012_50121501_66_dialog_content = "Datang sekarang, Carleen. Tidak perlu terlalu formal.",
  ui_story_5012_50121501_67_dialog_content = "Kalian bersenang-senang di pasar?",
  ui_story_5012_50121501_68_dialog_content = "Iya, kami melihat berbagai macam hiasan yang indah. Kurasa kami akan ke pasar lagi sebelum pulang, dan membeli beberapa hiasan untuk mempercantik Soroz.",
  ui_story_5012_50121501_69_dialog_content = "Soroz?",
  ui_story_5012_50121501_70_dialog_content = "Colossus milikku.",
  ui_story_5012_50121501_71_dialog_content = "Ah... Nama yang sangat bagus.",
  ui_story_5012_50121501_72_dialog_content = "Tapi, kenapa kamu membeli bintang raksasa untuk pohon kelip?",
  ui_story_5012_50121501_73_dialog_content = "Sebenarnya, itu sangat besar. Hanya ada satu pohon yang cukup besar untuk dipasangi bintang itu... Pohon yang ada di Winter Palace.",
  ui_story_5012_50121501_74_dialog_content = "Jangan-jangan Lola lupa lagi membelinya tahun ini...?",
  ui_story_5012_50121501_75_dialog_content = "Hei! PlayerName! Akhirnya, kamu pulang juga!",
  ui_story_5012_50121501_76_dialog_content = "Sini, biar kubantu membawa barang belanjaanmu ke gudang kami! Novio, bagaimana kalau kamu mengajak PlayerName ke aula besar saja sekarang?",
  ui_story_5012_50121501_X76_dialog_content = "Ayolah, serahkan saja padaku! Biar kubantu langsung menaruh semuanya di gudang!",
  ui_story_5012_50121501_X77_dialog_content = "Novio, ajak PlayerName ke aula!",
  ui_story_5012_50121501_77_dialog_content = "Seingatku arah ke gudang tidak lewat sana, Lola...",
  ui_story_5012_50121501_78_dialog_content = "Sampai jumpa lagi!",
  ui_story_5012_50121501_S1_dialog_content = "Dia masih saja belum berubah... Tidak ada kemajuan sama sekali.",
  ui_story_5012_50121501_S2_dialog_content = "Ayo, masuk ke dalam.",
  ui_story_5012_50121501_79_dialog_content = "Tapi, kamu harus menutup matamu dulu, PlayerName.",
  ui_story_5012_50121501_80_dialog_content = "Hah? Buat apa?",
  ui_story_5012_50121501_81_dialog_content = "Nanti kamu akan tahu. Nah, sekarang pegang tanganku dan ikuti aku. Hati-hati.",
  ui_story_5012_50121501_S3_dialog_content = "(Misterius sekali... Kenapa dia tidak bertanya dulu apa aku suka kejutan...?)",
  ui_story_5012_50121501_S4_dialog_content = "(Begitu membuka mata, apakah aku akan terjebak dalam ilusi lain?)",
  ui_story_5012_50121501_S5_dialog_content = "Mungkin?",
  ui_story_5012_50121501_S6_dialog_content = "Kok kamu bisa tahu apa yang kupikirkan!?",
  ui_story_5012_50121501_S7_dialog_content = "Novio, Saya harap Anda ingat bahwa saya diundang untuk menghadiri perayaan Tahun Baru, bukan—",
  ui_story_5012_50121501_S8_dialog_content = "Ah, kita sudah sampai.",
  ui_story_5012_50121501_S9_dialog_content = "Master Novio...",
  ui_story_5012_50121501_82_dialog_content = "Kamu boleh membuka matamu setelah hitungan ketiga.",
  ui_story_5012_50121501_83_dialog_content = "Satu...",
  ui_story_5012_50121501_S10_dialog_content = "Tunggu! Jangan buru-buru!",
  ui_story_5012_50121501_S11_dialog_content = "Ahh!",
  ui_story_5012_50121501_S12_dialog_content = "Aku tak bisa melepasnya... Ini terlalu berbahaya.",
  ui_story_5012_50121501_84_dialog_content = "Dua...",
  ui_story_5012_50121501_S13_dialog_content = "Hampir!",
  ui_story_5012_50121501_S14_dialog_content = "Sedikit lagi—",
  ui_story_5012_50121501_85_dialog_content = "Tiga!",
  ui_story_5012_50121501_86_dialog_content = "<size=45>!!!</size>",
  ui_story_5012_50121501_87_dialog_content = "Selamat Tahun Baru, PlayerName.",
  ui_story_5012_50121501_88_dialog_content = "Selamat Tahun Baru, semuanya!",
  ui_story_5012_50121501_89_dialog_content = "Pohon kelipnya... berwarna biru!",
  ui_story_5012_50121501_90_dialog_content = "Lihat! Lady Nikinis dan anak-anak itu juga kemari untuk menyanyikan lagu syukur!",
  ui_story_5012_50121501_91_dialog_content = "Selamat Tahun Baru, Yang Mulia.",
  ui_story_5012_50121501_92_dialog_content = "Sudah siap, anak-anak?",
  ui_story_5012_50121501_93_dialog_content = "Siap!",
  ui_story_5012_50121501_94_dialog_content = "Ayo kita mulai!",
  ui_story_5012_50121501_95_dialog_content = "\"Kerajaan utara, ibu kami yang murah hati...♪\"",
  ui_story_5012_50121501_96_dialog_content = "\"Negeri banyak legenda, tak seperti yang lain...♪\"",
  ui_story_5012_50121501_97_dialog_content = "\"Puncak yang tinggi dan bersalju, dan hutan hijau...♪\"",
  ui_story_5012_50121501_98_dialog_content = "\"Danau laksana cermin, dan pantai yang sangat tenang...♪\"",
  ui_story_5012_50121501_99_dialog_content = "\"Melindungi dan menjaganya, itulah yang kuminta...♪\"",
  ui_story_5012_50121501_100_dialog_content = "\"Tolong tunjukkan jalan!♪\"",
  ui_story_5012_50121501_101_dialog_content = "\"Karena kaulah anugerah dari angin dan salju. Bintang yang senantiasa bersinar dalam gelapnya malam...♪\"",
  ui_story_5012_50121501_102_dialog_content = "\"Aurora yang bersinar dalam hati kami dengan kasih ibu...♪\"",
  ui_story_5012_50121501_103_dialog_content = "\"Maka kami teriakkan \"Demi Utara!\" pada cahaya di angkasa.♪\"",
  ui_story_5012_50121501_104_dialog_content = "Ini untukmu, Carleen! Selamat Tahun Baru!",
  ui_story_5012_50121501_105_dialog_content = "Bukankah ini pita yang tadi kita lihat di pasar?",
  ui_story_5012_50121501_106_dialog_content = "Benar! Dari raut wajahmu, aku langsung tahu bahwa kamu sangat menyukainya. Jadi, aku membelinya untukmu!",
  ui_story_5012_50121501_107_dialog_content = "Karena ini hadiah, kamu pasti mau menerimanya... Iya, 'kan?",
  ui_story_5012_50121501_108_dialog_content = "Ini sangat bagus... Terima kasih.",
  ui_story_5012_50121501_109_dialog_content = "Selamat Tahun Baru, Vice.",
  ui_story_5012_50121501_110_dialog_content = "Huaaaaaa! Aku tidak mengerti, Master Novio!",
  ui_story_5012_50121501_111_dialog_content = "Anak-anak yang lain mendapat mainan dan permen, tapi kenapa...",
  ui_story_5012_50121501_112_dialog_content = "Kenapa aku mendapat buku sejarah Northland LAGI tahun ini?!?",
  ui_story_5012_50121501_113_dialog_content = "Aku memberimu jilid tiga tahun lalu. Berarti, tahun ini kamu mendapat jilid empat.",
  ui_story_5012_50121501_114_dialog_content = "Bukan itu intinya!",
  ui_story_5012_50121501_115_dialog_content = "Pikiranmu akan jadi lebih tajam dengan belajar. Kamu akan jadi lebih pintar kalau lebih banyak membaca.",
  ui_story_5012_50121501_116_dialog_content = "Siapa yang tahu? Mungkin tahun depan, kamu tidak akan lupa membeli bintang untuk ditaruh di puncak pohon?",
  ui_story_5012_50121501_117_dialog_content = "...",
  ui_story_5012_50121501_118_dialog_content = "Yang Mulia.",
  ui_story_5012_50121501_119_dialog_content = "Halo, PlayerName. Apa kamu butuh sesuatu?",
  ui_story_5012_50121501_120_option_content = "(Menyerahkan hadiah)",
  ui_story_5012_50121501_121_dialog_content = "Ini...",
  ui_story_5012_50121501_122_dialog_content = "Selamat Tahun Baru... Shaya.",
  ui_story_5012_50121501_123_dialog_content = "Terima kasih, PlayerName.",
  ui_story_5012_50121501_124_dialog_content = "Selamat Tahun Baru."
}
return config
